// =============================================================================
// Dungeon Loot — transitional monolith (strangler migration).
//
// This is the game's original inline <script>, moved VERBATIM out of index.html
// into an ES module so Vite can build it and so pure logic can be carved out of
// it incrementally (see docs/DECISIONS.md ▸ D6 and docs/CHANGELOG.md). Nothing in
// the game logic below was changed in the move — only the trailing window bridge
// was appended so the inline on*= handlers keep resolving now that this is a
// module rather than a classic global script.
//
// As modules are extracted, code leaves this file (imported from real src/
// modules) and the file shrinks toward empty. Excluded from coverage until then.
// =============================================================================

// ── Extracted modules (see docs/CHANGELOG.md) ──
import { shadeColor, hexA, _parseRGBA } from '../utils/color.js';
import { milestonePower, rankScale, skillManaCost } from '../systems/skillMath.js';
import { rated, ratePct, SKILL_RATING } from '../systems/ratings.js';
import { CHANGELOG } from '../data/changelog.js';
import { terrainPacksInUse } from '../data/terrainPacks.js';
import { renderProcMap } from '../render/procTerrain.js';
import { DECOR_INDEX, DECOR_ATLAS } from '../assets/decorAtlas.js';
import { INTERIORS_FLOORS, INTERIORS_WALLS, INTERIORS_ATLAS } from '../assets/interiorsAtlas.js';
import { createLeaderboardRepo } from '../persistence/leaderboardRepo.js';

// ══════════════════════════════════════════
// CONSTANTS & DATA
// ══════════════════════════════════════════

const TILE = 16;

// ── PALETTE ── canvas/JS mirror of the CSS design tokens (see the :root block
// at the top of the <style>). It reads the LIVE token values off :root, so
// canvas UI colors are the single source of truth as the DOM palette — change a
// token once and both the DOM and the canvas follow. Use these for UI-semantic
// canvas colors (bars, gold, xp, loot-tier tints, HUD text); genuinely bespoke
// pixel-art / particle / procedural-terrain colors stay as art, not tokens.
const PALETTE = (() => {
  const cs = getComputedStyle(document.documentElement);
  const t = n => cs.getPropertyValue('--' + n).trim() || '#000';
  return {
    bg: t('bg'), panel: t('panel'), border: t('border'), frame: t('frame'),
    text: t('text'), textMuted: t('text-muted'), gold: t('gold'), xp: t('xp'),
    hp: t('hp'), mp: t('mp'), danger: t('danger'), success: t('success'),
    warn: t('warn'), info: t('info'), interactive: t('interactive'),
    ink: t('ink'), paper: t('paper'),
    junk: t('junk'), normal: t('normal'), uncommon: t('uncommon'),
    rare: t('rare'), epic: t('epic'), legendary: t('legendary'), unique: t('unique'),
  };
})();

// Map dimensions in tiles. No longer fixed: floors grow with difficulty (see
// mapSizeFor) so harder tiers and deeper Endless floors are physically larger
// maps. generateMap() sets these per floor; buildTown() resets them to the base
// size (the town's building layout is hand-placed for a 20×20 plaza). BASE_* is
// the Normal / town size and the baseline for the area-ratio density scaling.
const BASE_MAP_W = 20, BASE_MAP_H = 20;
let MAP_W = BASE_MAP_W, MAP_H = BASE_MAP_H;

// Each equipment slot, with the base item names that roll for it.
// `label` is the plain slot name; `sprite` is its pixel tile (referenced directly).
// Use slotLabelIcon(slot) to prefix the icon where a slot label is shown with art.
const SLOTS = {
  weapon: { label: 'Weapon', sprite: 'w_sword', names: ['Shortsword','Arming Sword','Rapier','Greatsword','Claymore','Hatchet','War Axe','Greataxe','Battleaxe','Dagger','Stiletto','Kris','Mace','Morningstar','Maul','Spear','Halberd','Pike','Staff','Wand','Shortbow','Longbow','Scythe','War Scythe'] },
  offhand:{ label: 'Off-Hand', sprite: 'a_shield', names: ['Buckler','Kite Shield','Tower Shield','Tome','Focus','Quiver','Parrying Dagger'] },
  head:   { label: 'Head',   sprite: 'a_head',   names: ['Helm','Cap','Crown','Hood','Circlet'] },
  chest:  { label: 'Chest',  sprite: 'a_chest',  names: ['Chestplate','Robe','Cuirass','Tunic','Mail'] },
  hands:  { label: 'Hands',  sprite: 'a_hands',  names: ['Gauntlets','Gloves','Bracers','Grips'] },
  legs:   { label: 'Legs',   sprite: 'a_legs',   names: ['Greaves','Leggings','Tassets','Trousers'] },
  ring:   { label: 'Ring',   sprite: 'a_ring',   names: ['Ring','Band','Signet','Loop'] },
  amulet: { label: 'Amulet', sprite: 'a_amulet', names: ['Amulet','Pendant','Necklace','Talisman','Charm'] },
};
// Icon + name for a slot, for the few places a slot label should show its art.
function slotLabelIcon(slot) { const s = SLOTS[slot]; return s ? `${dlIcon(s.sprite, 16)} ${s.label}` : ''; }
const SLOT_KEYS = Object.keys(SLOTS);

// Roll weights for which slot a dropped item belongs to.
const SLOT_WEIGHTS = { weapon:22, chest:15, head:13, hands:13, legs:13, ring:12, amulet:12, offhand:11 };

// ── AFFIX SYSTEM ──
// Beyond its headline (weapon DMG / armor DEF), an item carries up to a
// rarity-gated number of bonus affixes, split into two independent pools: gear
// STATS (+ATK, +Crit %, …) and ATTRIBUTES (+Might, +Luck, …). The caps below are
// MAXIMUMS — the real count is rolled up to them, so a legendary *can* land 4
// stats + 2 attributes but usually rolls fewer. No stat or attribute is ever
// duplicated on one item, and an affix can't repeat the slot's headline.
// An item carries at most ONE attribute modifier and up to FIVE stat modifiers,
// reached at legendary/unique. Lower rarities ramp up to that ceiling.
const TIER_AFFIX_CAPS = {
  junk:      { stat: 0, attr: 0 },
  normal:    { stat: 1, attr: 0 },
  uncommon:  { stat: 2, attr: 0 },
  rare:      { stat: 3, attr: 1 },
  epic:      { stat: 4, attr: 1 },
  legendary: { stat: 5, attr: 1 },
  unique:    { stat: 5, attr: 1 },
};
// Which stats / attributes each slot is allowed to roll. A slot can never roll
// anything outside its pool (no Attack on boots, no Defense on a ring), which is
// what gives each piece a recognisable identity.
// Note: Luck is now an *attribute*, not a gear stat — the old LCK stat is kept
// only so legacy items keep working, and never appears in these pools, so "Luck"
// in the UI always refers to the attribute.
// Each pool is intentionally LARGER than the rarity cap (5 stats / 1 attr at the
// top), so even a fully-rolled item always has spare types to transmute into —
// that keeps the Enchanter's modifier (🔄) reroll alive on every property. A
// slot's own headline (weapon DMG, armor DEF/ATK) is never listed here, since the
// headline already occupies that stat and would only waste a pool slot.
const SLOT_AFFIX_POOLS = {
  // A weapon slot lists BOTH power/speed families; itemStatPool() then hard-gates
  // them by the weapon's category — a martial weapon keeps only SKILLPWR/ATKSPD, a
  // caster weapon (Staff/Wand) only SPELLPWR/CASTSPD — so the two never mix.
  weapon: { stats: ['ATK','ACC','CRIT','CRITDMG','IDMG','DBLSTRIKE','CLEAVE','BOSSDMG','EXEC','PEN','LEECH','MPLEECH','SPELLPWR','SKILLPWR','BLEED','STUNPWR','ATKSPD','CASTSPD'], attrs: ['might','agility','spirit'] },
  head:   { stats: ['HP','MP','REGEN','CRIT','CRITDMG','SPD','MAGICFIND','XPGAIN','SPELLPWR','SKILLPWR','CDR','MCR','CASTSPD','DODGE','MPKILL','MATFIND'], attrs: ['vitality','spirit','luck'] },
  chest:  { stats: ['HP','REGEN','MP','DR','BLOCK','THORNS','HPKILL','DODGE','MAGICFIND','TENAC'], attrs: ['vitality','spirit','luck'] },
  hands:  { stats: ['CRIT','ACC','CRITDMG','IDMG','DBLSTRIKE','SPD','PEN','LEECH','EXEC','CDR','CLEAVE','BLOCK','THORNS','ATKSPD','SKILLPWR'], attrs: ['might','agility','spirit'] },
  legs:   { stats: ['SPD','HP','REGEN','DODGE','DR','BLOCK','MP','GOLDFIND','XPGAIN','HPKILL','TENAC'], attrs: ['agility','vitality','luck'] },
  ring:   { stats: ['CRIT','ACC','CRITDMG','ATK','IDMG','SKILLPWR','LEECH','MPLEECH','GOLDFIND','MAGICFIND','MATFIND','HP','MP','DEF','DBLSTRIKE','BOSSDMG','EXEC','PEN','MCR','MPKILL','CLEAVE'], attrs: ['might','agility','luck','spirit','vitality'] },
  amulet: { stats: ['MP','HP','REGEN','SPELLPWR','CASTSPD','CDR','MCR','MPLEECH','MPKILL','HPKILL','THORNS','MAGICFIND','DR','ATK','DEF','BOSSDMG','GOLDFIND','XPGAIN','MATFIND','TENAC'], attrs: ['spirit','luck','vitality','might','agility'] },
  // Off-hands: defensive layers + caster utility. A shield's BLOCK headline already
  // flows through totalStat('BLOCK') into combat, so it needs no special-casing.
  // Like weapons, the power/speed stats here are gated by family in itemStatPool()
  // (caster Tome/Focus → SPELLPWR/CASTSPD; shields & martial off-hands → SKILLPWR).
  offhand:{ stats: ['BLOCK','DR','THORNS','HP','REGEN','MP','SPELLPWR','CASTSPD','SKILLPWR','CDR','MCR','CRIT','DODGE','TENAC'], attrs: ['vitality','spirit','luck'] },
};
// Skill/Spell power & their speed levers are mutually exclusive by gear type. The
// two families below are the ones itemStatPool() drops from the "wrong" gear so a
// martial piece can never roll a caster amp (or vice-versa) on drop, reroll or forge.
const MARTIAL_POWER_STATS = ['SKILLPWR', 'ATKSPD'];
const CASTER_POWER_STATS  = ['SPELLPWR', 'CASTSPD'];
// Is this a CASTER piece (rolls Spell Power / Cast Speed) rather than a martial one
// (Skill Power / Attack Speed)? Only weapons and off-hands split this way; armour and
// jewelry aren't category-gated (their pools above simply lean one way by design).
function isCasterGear(item) {
  if (!item) return false;
  if (item.slot === 'weapon') {
    const sub = weaponSubType(item);
    const cat = sub ? WEAPON_SUBTYPES[sub].cat : weaponBaseType(item);
    return cat === 'Staff';                 // Staff & Wand are the caster weapons
  }
  if (item.slot === 'offhand') return item.off === 'caster'; // Tome / Focus
  return false;
}
// The stat-affix pool an ITEM can actually hold — its slot pool with the power/speed
// families it isn't allowed hard-filtered out. Routing every affix consumer through
// this keeps the melee-only-Skill-Power / caster-only-Spell-Power gate consistent
// across drops, the Enchanter (reroll & transmute), the tooltip preview and curses.
function itemStatPool(item) {
  const pool = (SLOT_AFFIX_POOLS[item.slot]?.stats) || [];
  if (item.slot !== 'weapon' && item.slot !== 'offhand') return pool;
  const drop = isCasterGear(item) ? MARTIAL_POWER_STATS : CASTER_POWER_STATS;
  return pool.filter(s => !drop.includes(s));
}

// ── ITEM BASE PROFILES ──
// Within a slot, the chosen base (Sword vs Dagger, Helm vs Hood, Amulet vs
// Pendant) now shapes its stats — so the base you pick at the Forge, and the
// base a drop rolls, actually matters instead of being pure flavour.
//   • Weapons scale their damage (`dmg`) and how wide the low–high range rolls
//     (`spread`), so an Axe hits harder but swingier than a steady Dagger.
//   • Armor scales its defence (`def`); gloves also scale their bonus attack
//     (`atk`), so heavy plate guards more while light pieces lean offensive. Each
//     armor base ALSO carries one INNATE signature stat (`innate`) so a base has a
//     role beyond raw DEF: heavier bases bank a DEFENSIVE stat (Helm HP, Chestplate
//     damage-reduction, Gauntlets block, Greaves regen); lighter bases grant
//     evasion/offense/utility (Hood dodge, Cap magic-find, Circlet cooldowns, Grips
//     crit). Same DEF as before — the innate is a net identity, and the equip
//     requirement (see ARMOR_REQ) is the price of a base's raw armour, so no base
//     is strictly best.
//   • Jewelry has no headline stat, so each base instead carries one INNATE
//     signature stat (`innate`) — a Signet always finds gold, a Necklace always
//     boosts spell power. Innate stats are protected like a headline: they show
//     in the preview and survive the Enchanter's rerolls (see headlineStats).
// Multipliers default to 1 (a neutral base) when a key is omitted.
const BASE_STATS = {
  // weapons — dmg scales the hit, spread scales the high–low damage range
  Sword:  { dmg: 1.00, spread: 0.40 },   // balanced all-rounder
  Axe:    { dmg: 1.20, spread: 0.75 },   // big, swingy hits
  Dagger: { dmg: 0.72, spread: 0.18 },   // light but very consistent
  Staff:  { dmg: 0.85, spread: 0.30 },   // caster reach over raw power
  Bow:    { dmg: 0.90, spread: 0.55 },   // ranged, variable
  Mace:   { dmg: 1.15, spread: 0.45 },   // heavy, fairly steady
  Spear:  { dmg: 1.00, spread: 0.35 },   // reliable reach
  Scythe: { dmg: 1.10, spread: 0.65 },   // wide, swingy arc
  // head — DEF unchanged; each base adds its signature stat (tank / caster / evasion / farmer)
  Helm: { def: 1.25, innate: 'HP' }, Cap: { def: 0.80, innate: 'MAGICFIND' }, Crown: { def: 0.85, innate: 'SPELLPWR' }, Hood: { def: 0.90, innate: 'DODGE' }, Circlet: { def: 0.80, innate: 'CDR' },
  // chest — mitigation / retaliation / crowd-control / evasion / caster
  Chestplate: { def: 1.30, innate: 'DR' }, Robe: { def: 0.70, innate: 'MP' }, Cuirass: { def: 1.10, innate: 'THORNS' }, Tunic: { def: 0.85, innate: 'DODGE' }, Mail: { def: 1.15, innate: 'TENAC' },
  // hands — def vs atk lean, plus a signature stat (block / caster / sustain / crit)
  Gauntlets: { def: 1.25, atk: 0.90, innate: 'BLOCK' }, Gloves: { def: 0.85, atk: 1.15, innate: 'CDR' }, Bracers: { def: 1.05, atk: 1.00, innate: 'LEECH' }, Grips: { def: 0.90, atk: 1.10, innate: 'CRIT' },
  // legs — sustain / on-kill / mobility / caster
  Greaves: { def: 1.25, innate: 'REGEN' }, Leggings: { def: 0.85, innate: 'MP' }, Tassets: { def: 1.10, innate: 'HPKILL' }, Trousers: { def: 0.90, innate: 'SPD' },
  // jewelry — each base's signature innate stat (drawn from its slot pool)
  Ring: { innate: 'CRIT' }, Band: { innate: 'HP' }, Signet: { innate: 'GOLDFIND' }, Loop: { innate: 'MP' },
  Amulet: { innate: 'MP' }, Pendant: { innate: 'HP' }, Necklace: { innate: 'SPELLPWR' }, Talisman: { innate: 'MAGICFIND' }, Charm: { innate: 'REGEN' },
  // off-hands — `off` family decides which headline an off-hand carries: shields
  // bring DEF + a flat BLOCK %, caster off-hands bring Spell Power, ranged/dual
  // off-hands bring a little Attack (the parry blade also blocks). See applyBaseStats.
  Buckler:        { off:'shield', def:0.7, block:8 },
  'Kite Shield':  { off:'shield', def:1.0, block:12 },
  'Tower Shield': { off:'shield', def:1.4, block:18 },
  Tome:           { off:'caster', spellpwr:1.4 },
  Focus:          { off:'caster', spellpwr:1.0 },
  Quiver:         { off:'ranged', atk:1.1 },
  'Parrying Dagger': { off:'dual', atk:0.8, block:6 },
};
function baseProfile(name) { return BASE_STATS[name] || {}; }

// ── WEAPON SUB-TYPES ──
// A second layer UNDER the eight weapon categories (Sword, Axe, …): each category
// splits into distinct sub-types that share the category's class restriction,
// style and icon but roll their OWN damage profile, reach, attack style and affix
// bias — so a one-handed Rapier (fast, crit, reach) and a two-handed Greatsword
// (slow, heavy, cleaving) both read as "Sword" to the class lock yet play nothing
// alike. `hands` is 1 or 2 (a two-hander forgoes the off-hand slot unless Titan's
// Grip is learned). `dmg`/`spread` scale the headline exactly like BASE_STATS, so
// the category baselines below match the old per-category numbers (no balance
// reset). `style`/`range` override the category defaults; `bias` weights which
// affixes the sub-type tends to roll (a weight, never an exclusion — every weapon
// can still roll anything in its slot pool). Bias keys must live in the weapon
// affix pool. Icons reuse the category's existing art (no new sprites).
const WEAPON_SUBTYPES = {
  // Swords
  'Shortsword':  { cat:'Sword',  hands:1, dmg:0.92, spread:0.30, style:'flurry', range:1, bias:{ DBLSTRIKE:4, CRIT:3 } },
  'Arming Sword':{ cat:'Sword',  hands:1, dmg:1.00, spread:0.40, style:'slash',  range:1, bias:{ IDMG:3, ATK:3 } },
  'Rapier':      { cat:'Sword',  hands:1, dmg:0.85, spread:0.22, style:'thrust', range:2, bias:{ CRIT:4, CRITDMG:3, PEN:3 } },
  'Greatsword':  { cat:'Sword',  hands:2, dmg:1.85, spread:0.70, style:'cleave', range:1, bias:{ CLEAVE:4, BOSSDMG:3, IDMG:3 } },
  'Claymore':    { cat:'Sword',  hands:2, dmg:1.70, spread:1.00, style:'reap',   range:1, bias:{ CRITDMG:4, EXEC:3, LEECH:3 } },
  // Axes
  'Hatchet':     { cat:'Axe',    hands:1, dmg:1.00, spread:0.55, style:'flurry', range:1, bias:{ DBLSTRIKE:4, ATK:3 } },
  'War Axe':     { cat:'Axe',    hands:1, dmg:1.15, spread:0.70, style:'cleave', range:1, bias:{ CLEAVE:4, IDMG:3 } },
  'Greataxe':    { cat:'Axe',    hands:2, dmg:2.00, spread:1.10, style:'cleave', range:1, bias:{ CLEAVE:4, BOSSDMG:3, IDMG:3 } },
  'Battleaxe':   { cat:'Axe',    hands:2, dmg:1.80, spread:0.90, style:'reap',   range:1, bias:{ EXEC:4, CRITDMG:3 } },
  // Daggers
  'Dagger':      { cat:'Dagger', hands:1, dmg:0.72, spread:0.18, style:'flurry', range:1, bias:{ CRIT:4, DBLSTRIKE:3 } },
  'Stiletto':    { cat:'Dagger', hands:1, dmg:0.68, spread:0.14, style:'thrust', range:1, bias:{ PEN:4, CRIT:3 } },
  'Kris':        { cat:'Dagger', hands:1, dmg:0.78, spread:0.30, style:'flurry', range:1, bias:{ LEECH:4, BLEED:4 } },
  // Maces
  'Mace':        { cat:'Mace',   hands:1, dmg:1.10, spread:0.40, style:'crush',  range:1, bias:{ IDMG:3, BOSSDMG:2 } },
  'Morningstar': { cat:'Mace',   hands:1, dmg:1.18, spread:0.55, style:'crush',  range:1, bias:{ BOSSDMG:4, IDMG:3 } },
  'Maul':        { cat:'Mace',   hands:2, dmg:1.95, spread:0.60, style:'crush',  range:1, bias:{ STUNPWR:5, BOSSDMG:3 } },
  // Spears
  'Spear':       { cat:'Spear',  hands:1, dmg:1.00, spread:0.35, style:'thrust', range:2, bias:{ PEN:3, CRIT:3 } },
  'Halberd':     { cat:'Spear',  hands:2, dmg:1.75, spread:0.55, style:'cleave', range:2, bias:{ CLEAVE:4, IDMG:3 } },
  'Pike':        { cat:'Spear',  hands:2, dmg:1.65, spread:0.45, style:'thrust', range:3, bias:{ PEN:4, BOSSDMG:3 } },
  // Staves (caster)
  'Staff':       { cat:'Staff',  hands:2, dmg:0.85, spread:0.30, style:'bolt',   range:4, bias:{ SPELLPWR:4, MPLEECH:2 } },
  'Wand':        { cat:'Staff',  hands:1, dmg:0.70, spread:0.25, style:'bolt',   range:4, bias:{ SPELLPWR:4, CRIT:2 } },
  // Bows (ranged)
  'Shortbow':    { cat:'Bow',    hands:2, dmg:0.88, spread:0.45, style:'shot',   range:4, bias:{ DBLSTRIKE:4, CRIT:2 } },
  'Longbow':     { cat:'Bow',    hands:2, dmg:0.98, spread:0.70, style:'shot',   range:5, bias:{ CRITDMG:4, BOSSDMG:3 } },
  // Scythes
  'Scythe':      { cat:'Scythe', hands:2, dmg:1.10, spread:0.65, style:'reap',   range:1, bias:{ LEECH:4, EXEC:3 } },
  'War Scythe':  { cat:'Scythe', hands:2, dmg:1.80, spread:0.80, style:'reap',   range:2, bias:{ CLEAVE:3, LEECH:3 } },
};
// Sub-type keys sorted longest-first so a name match prefers the most specific
// ("War Axe" beats "Axe", "Arming Sword" beats any bare word).
const SUBTYPE_KEYS = Object.keys(WEAPON_SUBTYPES).sort((a, b) => b.length - a.length);
// The sub-type carried by an item's name (longest match wins), or null for a
// legacy bare-category weapon ("Ancient Sword of Power" → null, resolved by the
// category fallback in weaponBaseType).
function weaponSubType(item) {
  const nm = (item && item.name) || '';
  for (const s of SUBTYPE_KEYS) if (nm.includes(s)) return s;
  return null;
}
function subTypeData(name) { return WEAPON_SUBTYPES[name] || null; }
// Resolve the weapon CATEGORY (Sword, Axe, …) from a sub-type or bare name.
function weaponCategoryOf(name) {
  const d = WEAPON_SUBTYPES[name];
  if (d) return d.cat;
  return WEAPON_STYLES[name] ? name : null; // already a category, or unknown
}
// How many hands a weapon (item or base-name) needs: two-handers forgo off-hands.
function weaponHandsOf(nameOrItem) {
  const name = typeof nameOrItem === 'string' ? nameOrItem
    : (nameOrItem ? weaponSubType(nameOrItem) : null);
  const d = name && WEAPON_SUBTYPES[name];
  return d ? d.hands : 1; // legacy bare weapons count as one-handed
}
function isTwoHander(item) {
  return !!(item && item.slot === 'weapon' && weaponHandsOf(item) === 2);
}
// Apply a base's headline (and jewelry innate) stats onto a fresh item's stats
// object. Shared by the Forge's blank pieces and generateItem's drops so both
// honour the base. Records any innate jewelry stat on item.baseStats so the
// Enchanter treats it as protected (see headlineStats).
function applyBaseStats(item, baseName, lvl, mult, dmgMult, opts = {}) {
  const bp = baseProfile(baseName);
  const slot = item.slot;
  if (slot === 'weapon') {
    // Damage profile comes from the weapon SUB-TYPE (Greatsword vs Rapier); a
    // legacy bare-category name falls back to its BASE_STATS category baseline.
    const sd = WEAPON_SUBTYPES[baseName] || BASE_STATS[weaponCategoryOf(baseName)] || bp;
    const dm = sd.dmg != null ? sd.dmg : 1;
    const sp = sd.spread != null ? sd.spread : 0.4;
    const base = Math.max(1, Math.floor((2 + lvl * 1.2) * dmgMult * dm));
    const spread = Math.max(1, Math.floor(base * sp));
    item.stats.DMG = `${base}-${base + spread}`;
  } else if (slot === 'head' || slot === 'chest' || slot === 'hands' || slot === 'legs') {
    const slotDef = { chest: 1.3, legs: 1.0, head: 0.8, hands: 0.7 }[slot];
    item.stats.DEF = Math.max(1, Math.floor((1 + lvl) * mult * slotDef * (bp.def || 1)));
    if (slot === 'hands') item.stats.ATK = Math.max(1, Math.floor((1 + lvl * 0.35) * mult * 0.6 * (bp.atk || 1)));
    // Each armor base bakes in a signature stat (exactly like jewelry) so the base
    // you pick matters beyond raw DEF — heavy plate banks a defensive stat, light
    // gear an evasion/offense/utility one. Recorded on item.baseStats so it counts
    // as a protected headline (never rerolled, never eats the affix budget — see
    // headlineStats). fixed → midpoint for a deterministic Forge preview; drops
    // roll within the band.
    if (bp.innate) {
      if (opts.fixed) { const r = affixStatRange(bp.innate, lvl, mult); item.stats[bp.innate] = Math.round((r.min + r.max) / 2); }
      else item.stats[bp.innate] = affixStatValue(bp.innate, lvl, mult);
      item.baseStats = [bp.innate];
    }
  } else if (slot === 'offhand') {
    // Off-hands carry a headline shaped by their family (see BASE_STATS `off`):
    // shields → DEF + a flat BLOCK %, casters → Spell Power, ranged/dual → Attack
    // (the parry blade also blocks). The family is remembered on item.off so combat
    // (dual-wield, etc.) can read it without re-resolving by name.
    const off = bp.off || 'shield';
    item.off = off;
    if (off === 'shield') {
      item.stats.DEF = Math.max(1, Math.floor((1 + lvl) * mult * 0.7 * (bp.def || 1)));
      // Block headline is a RATING that scales with item level, so a shield keeps
      // pace with the rising block-opposition as you descend (a flat low-level
      // shield would fade to nothing deep). The effective block % is rating vs
      // depth (see blockChanceVs).
      item.stats.BLOCK = Math.max(2, Math.round((bp.block || 8) * (1 + lvl * 0.15)));
      item.baseStats = ['DEF', 'BLOCK'];
    } else if (off === 'caster') {
      const r = affixStatRange('SPELLPWR', lvl, mult);
      const sv = opts.fixed ? Math.round((r.min + r.max) / 2) : rnd(r.min, r.max);
      item.stats.SPELLPWR = Math.max(1, Math.round(sv * (bp.spellpwr || 1)));
      item.baseStats = ['SPELLPWR'];
    } else { // ranged (quiver) / dual (parry blade)
      item.stats.ATK = Math.max(1, Math.floor((1 + lvl * 0.35) * mult * 0.6 * (bp.atk || 1)));
      if (bp.block) { item.stats.BLOCK = Math.max(2, Math.round(bp.block * (1 + lvl * 0.15))); item.baseStats = ['ATK', 'BLOCK']; }
      else item.baseStats = ['ATK'];
    }
  } else if (bp.innate) {
    // ring / amulet: bake in the base's signature stat and mark it protected.
    // opts.fixed → use the band's midpoint so the Forge preview is deterministic
    // (matches the piece you'll get); drops roll a random value within the band.
    if (opts.fixed) {
      const r = affixStatRange(bp.innate, lvl, mult);
      item.stats[bp.innate] = Math.round((r.min + r.max) / 2);
    } else {
      item.stats[bp.innate] = affixStatValue(bp.innate, lvl, mult);
    }
    item.baseStats = [bp.innate];
  }
}

