const DEV_TUNABLES = [
  // ── Enemy scaling ──
  { id:'enemyHpMult',      group:'Enemy scaling', label:'All enemy HP',            unit:'x', min:0.25, max:3,   step:0.05,  def:1,    after:'spawn', get:()=>DEV.enemyHpMult,      set:v=>DEV.enemyHpMult=v },
  { id:'enemyDmgMult',     group:'Enemy scaling', label:'All enemy damage',        unit:'x', min:0.25, max:3,   step:0.05,  def:1,    after:'spawn', get:()=>DEV.enemyDmgMult,     set:v=>DEV.enemyDmgMult=v },
  { id:'enemyCountMult',   group:'Enemy scaling', label:'Enemies per floor',       unit:'x', min:0.25, max:3,   step:0.05,  def:1,    after:'spawn', get:()=>DEV.enemyCountMult,   set:v=>DEV.enemyCountMult=v, note:'capped at 40/floor' },
  { id:'depthExp',         group:'Enemy scaling', label:'Depth threat exponent',   unit:'',  min:1,    max:2,   step:0.02,  def:1.26, after:'spawn', get:()=>DEV.depthExp,         set:v=>DEV.depthExp=v,       note:'sharper = deep floors pull ahead faster' },
  { id:'depthDiv',         group:'Enemy scaling', label:'Depth threat divisor',    unit:'',  min:3,    max:20,  step:0.5,   def:8.5,  after:'spawn', get:()=>DEV.depthDiv,         set:v=>DEV.depthDiv=v,       note:'larger = gentler overall climb' },
  { id:'enemyHpPerFloor',  group:'Enemy scaling', label:'Enemy HP per floor',      unit:'',  min:3,    max:30,  step:0.5,   def:11,   after:'spawn', get:()=>DEV.enemyHpPerFloor,  set:v=>DEV.enemyHpPerFloor=v },
  { id:'enemyDmgPerFloor', group:'Enemy scaling', label:'Enemy damage per floor',  unit:'',  min:0.5,  max:6,   step:0.1,   def:1.9,  after:'spawn', get:()=>DEV.enemyDmgPerFloor, set:v=>DEV.enemyDmgPerFloor=v },
  { id:'enemyAccPerFloor', group:'Enemy scaling', label:'Enemy accuracy per floor',unit:'',  min:3,    max:20,  step:0.5,   def:10,   after:'spawn', get:()=>DEV.enemyAccPerFloor, set:v=>DEV.enemyAccPerFloor=v, note:'harder to dodge deeper' },
  // ── Bosses & elites ──
  { id:'bossHpMult',       group:'Bosses & elites', label:'Boss HP',      unit:'x', min:0.5, max:6, step:0.1,  def:2.2,  after:'spawn', get:()=>DEV.bossHpMult,   set:v=>DEV.bossHpMult=v },
  { id:'bossDmgMult',      group:'Bosses & elites', label:'Boss damage',  unit:'x', min:0.5, max:4, step:0.05, def:1.25, after:'spawn', get:()=>DEV.bossDmgMult,  set:v=>DEV.bossDmgMult=v },
  { id:'eliteHpMult',      group:'Bosses & elites', label:'Elite HP',     unit:'x', min:0.5, max:6, step:0.1,  def:2.2,  after:'spawn', get:()=>DEV.eliteHpMult,  set:v=>DEV.eliteHpMult=v },
  { id:'eliteDmgMult',     group:'Bosses & elites', label:'Elite damage', unit:'x', min:0.5, max:4, step:0.05, def:1.4,  after:'spawn', get:()=>DEV.eliteDmgMult, set:v=>DEV.eliteDmgMult=v },
  // ── Run modifiers ──
  { id:'antiGrindPerGap',  group:'Run modifiers', label:'Anti-grind per level over floor', unit:'',  min:0,   max:0.2,  step:0.005, def:0.06, after:'spawn', get:()=>DEV.antiGrindPerGap, set:v=>DEV.antiGrindPerGap=v, note:'foes toughen when you out-level the floor' },
  { id:'conquestScar',     group:'Run modifiers', label:'Conquest scar per tier',           unit:'',  min:0.8, max:1,    step:0.005, def:0.94, after:'hero',  get:()=>DEV.conquestScar,    set:v=>DEV.conquestScar=v,    note:'lower = harsher permanent scar' },
  { id:'endlessRate',      group:'Run modifiers', label:'Endless ramp rate',                unit:'',  min:0,   max:0.02, step:0.001, def:0.006,after:'spawn', get:()=>DEV.endlessRate,     set:v=>DEV.endlessRate=v,     note:'extra threat per Endless floor (76+)' },
  { id:'hazardDmgMult',    group:'Run modifiers', label:'Hazard damage',                    unit:'x', min:0,   max:3,    step:0.05,  def:1,    after:'spawn', get:()=>DEV.hazardDmgMult,   set:v=>DEV.hazardDmgMult=v },
  // ── Hero power ──
  { id:'hpPerVit',           group:'Hero power', label:'HP per Vitality',            unit:'', min:3,   max:30, step:0.5, def:11, after:'hero', get:()=>ATTR_FX.hpPerVit,       set:v=>ATTR_FX.hpPerVit=v },
  { id:'atkPrimary',         group:'Hero power', label:'Attack per primary attribute',unit:'', min:0.6, max:6,  step:0.1, def:2.4,after:'hero', get:()=>ATTR_DMG_PRIMARY,       set:v=>ATTR_DMG_PRIMARY=v },
  { id:'hpPerLevel',         group:'Hero power', label:'Max HP per level',           unit:'', min:2,   max:24, step:0.5, def:8,  after:'hero', get:()=>DEV.hpPerLevel,         set:v=>DEV.hpPerLevel=v },
  { id:'attrPointsPerLevel', group:'Hero power', label:'Attribute points per level', unit:'', min:1,   max:15, step:1,   def:5,  after:'none', get:()=>ATTR_POINTS_PER_LEVEL,  set:v=>ATTR_POINTS_PER_LEVEL=v, note:'applies to future level-ups' },
];
const DEV_TUNE_BY_ID = Object.fromEntries(DEV_TUNABLES.map(t => [t.id, t]));
const DEV_TUNE_KEY = 'dungeonLoot_devTune_v1';

// Clamp a raw slider value into a knob's range and snap to its step.
function devClamp(t, v) {
  v = Math.max(t.min, Math.min(t.max, +v));
  const snapped = Math.round((v - t.min) / t.step) * t.step + t.min;
  return Math.round(snapped * 1e6) / 1e6;   // kill float dust so 1.9 doesn't read 1.9000000002
}
// Is this knob currently away from its shipping default?
function devModified(t) { return Math.abs(t.get() - t.def) > 1e-9; }
// Human-readable value (multipliers show a ×; whole numbers drop the decimals).
function devFmt(t, v) {
  v = (v == null ? t.get() : v);
  const s = (Math.abs(v - Math.round(v)) < 1e-9) ? String(Math.round(v)) : String(Math.round(v * 1000) / 1000);
  return t.unit === 'x' ? s + '×' : s;
}
// Persist only the knobs that differ from default (keeps the blob small & forward-compatible).
function saveDevTune() {
  try {
    const o = {};
    for (const t of DEV_TUNABLES) if (devModified(t)) o[t.id] = t.get();
    if (Object.keys(o).length) localStorage.setItem(DEV_TUNE_KEY, JSON.stringify(o));
    else localStorage.removeItem(DEV_TUNE_KEY);
  } catch (e) {}
}
// Restore saved overrides on boot. Safe before the hero exists — it only writes
// the live values; the first recomputeMaxStats() then reads them.
function loadDevTune() {
  let o = null;
  try { o = JSON.parse(localStorage.getItem(DEV_TUNE_KEY) || 'null'); } catch (e) {}
  if (!o) return;
  let touchedHero = false;
  for (const t of DEV_TUNABLES) {
    if (typeof o[t.id] === 'number' && isFinite(o[t.id])) {
      t.set(devClamp(t, o[t.id]));
      if (t.after === 'hero') touchedHero = true;
    }
  }
  if (touchedHero && typeof recomputeMaxStats === 'function' && typeof player === 'object' && player) {
    try {
      recomputeMaxStats();
      player.hp = Math.min(player.hp, player.maxHp);
      player.mp = Math.min(player.mp, player.maxMp);
      if (typeof updateBars === 'function') updateBars();
    } catch (e) {}
  }
}
// Apply the side-effect a knob asks for once its value changes.
function devAfter(kind) {
  if (kind === 'hero') {
    if (typeof recomputeMaxStats === 'function' && player) {
      recomputeMaxStats();
      player.hp = Math.min(player.hp, player.maxHp);
      player.mp = Math.min(player.mp, player.maxMp);
      if (typeof updateBars === 'function') updateBars();
      if (typeof renderPanel === 'function') renderPanel();
    }
  }
}
// A slider moved: clamp, write the live value, refresh, persist, update the readout.
function onDevSlider(id, raw) {
  const t = DEV_TUNE_BY_ID[id]; if (!t) return;
  const v = devClamp(t, raw);
  t.set(v);
  devAfter(t.after);
  saveDevTune();
  syncDevRow(id);
}
// Restore one knob to its shipping default.
function resetDevTunable(id) {
  const t = DEV_TUNE_BY_ID[id]; if (!t) return;
  t.set(t.def);
  devAfter(t.after);
  saveDevTune();
  const el = document.querySelector(`#dev-tune-body input[data-id="${id}"]`);
  if (el) el.value = t.def;
  syncDevRow(id);
  if (typeof sfx === 'function') sfx('click');
}
// Restore every knob to defaults.
function resetAllDevTune() {
  let hero = false;
  for (const t of DEV_TUNABLES) { t.set(t.def); if (t.after === 'hero') hero = true; }
  if (hero) devAfter('hero');
  saveDevTune();
  renderDevTune();
  if (typeof sfx === 'function') sfx('click');
}
// Re-roll the current dungeon floor so spawn-side knob changes preview instantly.
function devRespawnFloor() {
  if (typeof inTown !== 'undefined' && inTown) { if (typeof log === 'function') log('Respawn floor: enter the dungeon first.'); return; }
  if (typeof generateMap === 'function') {
    generateMap();
    if (typeof updateBars === 'function') updateBars();
    if (typeof log === 'function') log('🛠️ Dev: floor re-rolled with the current tuning.', 'important');
    if (typeof sfx === 'function') sfx('stairs');
  }
}
// Refresh one row's value readout + modified styling without rebuilding the pane.
function syncDevRow(id) {
  const t = DEV_TUNE_BY_ID[id]; if (!t) return;
  const row = document.querySelector(`#dev-tune-body .dev-row[data-row="${id}"]`);
  if (!row) return;
  const val = row.querySelector('.dev-val');
  if (val) val.textContent = devFmt(t);
  row.classList.toggle('modified', devModified(t));
}
// Build the whole Dev pane from the registry, grouped.
function renderDevTune() {
  const body = document.getElementById('dev-tune-body');
  if (!body) return;
  const anyMod = DEV_TUNABLES.some(devModified);
  let html = `<div class="dev-intro">Live balance tuning — drag to rebalance the game on the spot. `
    + `<b>Hero</b> knobs apply instantly; <b>enemy &amp; floor</b> knobs bite on newly&nbsp;spawned foes, so hit `
    + `<b>Respawn floor</b> to preview. Changes save automatically.</div>`
    + `<div class="dev-actions">`
    + `<button class="dev-act-btn" onclick="devRespawnFloor()">🌀 Respawn floor</button>`
    + `<button class="dev-act-btn ${anyMod ? '' : 'is-off'}" onclick="resetAllDevTune()">↺ Reset all</button>`
    + `</div>`;
  let curGroup = null;
  for (const t of DEV_TUNABLES) {
    if (t.group !== curGroup) {
      if (curGroup !== null) html += `</div>`;
      curGroup = t.group;
      html += `<div class="dev-group-h">${curGroup}</div><div class="dev-group">`;
    }
    const noteHtml = t.note ? `<span class="dev-note">${t.note}</span>` : '';
    html += `<div class="dev-row ${devModified(t) ? 'modified' : ''}" data-row="${t.id}">`
      + `<div class="dev-row-top">`
      + `<span class="dev-label">${t.label}${noteHtml}</span>`
      + `<span class="dev-val">${devFmt(t)}</span>`
      + `<button class="dev-reset" title="Reset to default (${devFmt(t, t.def)})" onclick="resetDevTunable('${t.id}')">↺</button>`
      + `</div>`
      + `<input class="dev-slider" type="range" data-id="${t.id}" min="${t.min}" max="${t.max}" step="${t.step}" value="${t.get()}" `
      + `oninput="onDevSlider('${t.id}', this.value)">`
      + `</div>`;
  }
  if (curGroup !== null) html += `</div>`;
  body.innerHTML = html;
}
// A fresh attribute block — every attribute starts at ATTR_BASE. Used for new
// heroes, respecs (reset to base), and migrating older saves.
function baseAttributes() {
  const a = {};
  for (const k of ATTR_KEYS) a[k] = ATTR_BASE;
  return a;
}
// Points the player has actually spent (everything above the starting ATTR_BASE).
// This is what a respec refunds — the base block is never given back.
function spentAttrPoints() {
  return ATTR_KEYS.reduce((s, k) => s + Math.max(0, (player.attributes?.[k] || 0) - ATTR_BASE), 0);
}

// ── DEPTH THREAT ──
// The single most important difficulty lever: enemy power keeps climbing with
// depth. On top of the linear (per-floor) base stats, every floor multiplies
// enemy HP and damage by a growing factor.
//
// This curve is *polynomial*, not exponential — a deliberate choice. It starts
// gentle (an easy on-ramp), rises forever so every floor is strictly harder
// than the last, but grows slowly enough that the player's level, attribute, and
// gear growth can always catch up with enough grinding. Crucially the curve is
// tuned to OUTPACE level/attribute growth: the gap you must close keeps widening,
// so periodically you have to stop and grind or enhance gear to push on — and
// that pressure grows the deeper you go. There is intentionally NO hard wall: a
// pure exponential curve would eventually outrun any possible build and make some
// floor mathematically impossible, whereas this one stays beatable at every depth
// given the effort.
//   floor 1 → 1.0x   floor 10 → ~2.9x   floor 20 → ~5.8x   floor 30 → ~9.2x
//   floor 50 → ~17x   floor 100 → ~39x   (keeps rising, no ceiling)
function depthThreat(level) {
  // 1 + (depth-1)^1.26 / 8.5 — a touch gentler than before through the opening
  // floors (a softer on-ramp), then a steeper exponent so the climb pulls
  // progressively further ahead of the hero's linear power the deeper you dive.
  // That widening gap is what makes gear grinding/enhancing matter more and more.
  const d = Math.max(0, (level || 1) - 1);
  // Endless mode ramps a touch steeper than the raw depth continuation; a no-op
  // (×1) for the three finite difficulties (see endlessBite below).
  return (1 + Math.pow(d, DEV.depthExp) / DEV.depthDiv) * endlessBite();
}

// ── DUNGEON DIFFICULTY TIERS ──────────────────────────────────────────────
// The dungeon is 25 floors long, but a run doesn't end there. `dungeonLevel` is
// a SINGLE continuous depth counter that simply keeps climbing across tiers:
//   floors  1–25  → Normal    (tier 1)
//   floors 26–50  → Hardened  (tier 2)  — the same 25 floors, but more powerful
//   floors 51–75  → Brutal    (tier 3)  — harder still
//   floors 76+    → Endless   (tier 4)  — no cap, random bosses, ramps further
// Because depth stays continuous, every existing power/loot formula keeps
// working untouched — a Hardened floor 1 (dungeonLevel 26) is simply "as deep as
// floor 26", a smooth continuation rather than a jarring reset. What DOES reset
// per tier is the DISPLAYED floor number and the visual theme, so each
// difficulty replays the same 25-floor dungeon — just tougher and redder.
const FLOORS_PER_DIFF = 25;
const FINITE_DEPTH = FLOORS_PER_DIFF * 3; // last floor of the third (Brutal) tier
const DIFFS = [
  { n: 1, key: 'normal',   name: 'Normal',   color: '#bfe3ff', tint: 0.00 },
  { n: 2, key: 'hardened', name: 'Hardened', color: '#ffb38a', tint: 0.08 },
  { n: 3, key: 'brutal',   name: 'Brutal',   color: '#ff8366', tint: 0.14 },
  { n: 4, key: 'endless',  name: 'Endless',  color: '#ff5a78', tint: 0.20 },
];
// Difficulty tier (1–4) of a continuous depth; everything past the third tier is
// Endless.
function diffOf(dl) { return Math.min(4, Math.floor(((dl || 1) - 1) / FLOORS_PER_DIFF) + 1); }
function currentDifficulty() { return diffOf(dungeonLevel); }
function diffMeta(dl) { dl = (dl == null ? dungeonLevel : dl); return DIFFS[diffOf(dl) - 1]; }
function isEndless() { return dungeonLevel > FINITE_DEPTH; }
// The floor number shown to the player. Finite tiers cycle 1–25; Endless keeps
// climbing (1, 2, 3 … unbounded) from its own floor 1.
function displayFloor(dl) {
  dl = (dl == null ? dungeonLevel : dl);
  if (dl > FINITE_DEPTH) return dl - FINITE_DEPTH;
  return ((dl - 1) % FLOORS_PER_DIFF) + 1;
}
// The last floor of a FINITE difficulty (its boss floor 25). Endless never ends.
function isLastFiniteFloor() { return dungeonLevel <= FINITE_DEPTH && displayFloor() === FLOORS_PER_DIFF; }
// A short "Normal · Floor 3" label for logs and the HUD.
function floorLabel(dl) {
  dl = (dl == null ? dungeonLevel : dl);
  return `${DIFFS[diffOf(dl) - 1].name} · Floor ${displayFloor(dl)}`;
}
// A compact "Brutal 6" tag — difficulty tier name + per-tier floor number — for
// cards, banners and any tight spot that shows a continuous depth at a glance.
// (floorLabel is the longer "Brutal · Floor 6" prose form for logs/prose.)
function floorTag(dl) {
  dl = (dl == null ? dungeonLevel : dl);
  return `${DIFFS[diffOf(dl) - 1].name} ${displayFloor(dl)}`;
}
// Endless mode ramps a touch steeper than the raw depth continuation, creeping
// up the deeper you push. A no-op (×1) for the three finite difficulties.
function endlessBite() {
  if (dungeonLevel <= FINITE_DEPTH) return 1;
  return 1 + Math.min(0.6, (dungeonLevel - FINITE_DEPTH) * DEV.endlessRate);
}

// ── DUNGEON MAP SIZE ──────────────────────────────────────────────────────
// Floors get physically BIGGER with difficulty, and the per-floor monster count
// scales with the map's area so the density a player actually meets stays the
// same (see spawnEnemies) — a harder, larger floor simply holds proportionally
// more foes. Each finite tier is one fixed size, a step larger than the tier
// above it; Endless keeps expanding with depth, forever but sub-linearly so it
// never balloons into an unplayably huge, foe-choked map.
//   Normal 20×20 · Hardened 24×24 · Brutal 28×28 · Endless 32×32 and growing
const DIFF_SIZE_STEP = 4;  // tiles added to each side per finite tier above Normal
function mapSizeFor(dl) {
  const tier = diffOf(dl);                               // 1 Normal · 2 Hardened · 3 Brutal · 4 Endless
  const base = BASE_MAP_W + (tier - 1) * DIFF_SIZE_STEP; // 20 · 24 · 28 · 32
  if (tier < 4) return base;                             // finite tiers: one fixed size each
  // Endless: start at the tier-4 base, then creep upward with the Endless floor
  // number. The √ keeps it climbing endlessly while decelerating hard, so even
  // very deep floors stay navigable (floor 1 → 32, 26 → 37, 101 → 42, 401 → 52).
  const ef = Math.max(0, dl - (FINITE_DEPTH + 1));       // 0 on Endless floor 1, then 1, 2, 3 …
  return base + Math.floor(Math.sqrt(ef));
}
// How much larger (by area) the current floor is than the base 20×20. Drives the
// per-floor scaling of room count, hazards and monster count, so a bigger floor
// is a genuinely bigger dungeon at the same crowding rather than a sparse one.
function mapAreaRatio() { return (MAP_W * MAP_H) / (BASE_MAP_W * BASE_MAP_H); }

// ── DIFFICULTY PROGRESSION STATE ──
// How many finite tiers the hero has fully conquered (beaten the floor-25 boss
// of): 0 none, 1 Normal, 2 Hardened, 3 Brutal. The next tier up is then unlocked
// at the town Dungeon Gate, and Endless opens once Brutal (3) is conquered.
function diffClearedCount() { return Math.max(0, Math.min(3, player.diffCleared || 0)); }
function frontierDiff() { return Math.min(4, diffClearedCount() + 1); }
// Conquering each difficulty leaves a permanent scar: a stacking debuff to the
// hero's max HP and the damage they deal, so deeper tiers keep biting even as
// gear climbs. Multiplicative, ~6% per tier conquered (so Endless heroes fight
// at ~83% of their raw power).
function diffDebuffMult() { return Math.pow(DEV.conquestScar, diffClearedCount()); }

// Record reaching the current `dungeonLevel`: deepens both the all-time max (for
// display, gambling/crafting item level, leaderboards) and the currently-unlocked
// Gate frontier (the floors you can re-enter). A death can later shove gateFloor
// back; fighting forward raises it again here, re-opening the locked floors.
function recordDepth() {
  const prevMax = player.maxFloor || 1;
  player.maxFloor = Math.max(prevMax, dungeonLevel);
  player.gateFloor = Math.max(player.gateFloor || 1, dungeonLevel);
  // A fresh floor clears the transient combo/greed state and refreshes the chip.
  clearGreed(); updateObjectiveChip();
  if (player.maxFloor > prevMax) depthMilestone(prevMax, player.maxFloor);
  // Offer the optional risk/reward gate once this floor has finished building.
  setTimeout(() => { try { maybeGreedGate(); } catch (e) {} }, 0);
}

// ── MATERIAL GATING (natural kill-drops) ──
// Which crafting materials a KILL can drop is gated by how deep you're delving:
//   Scrap & Glimmer — Normal and deeper (Scrap the common bulk, Glimmer rarer)
//   Core            — Hardened and deeper
//   Chaos Orb       — Brutal and deeper (so Endless, past the third tier, drops all four)
// This gate is ONLY for kill-drops. Salvage is NOT gated this way — see
// salvageRanges(): breaking gear sheds whatever that item's rarity would give,
// regardless of difficulty, so a lucky high-rarity find is the one early route to
// a material your current tier can't drop from kills yet.
const MATERIAL_MIN_DIFF = { scrap: 1, glimmer: 1, core: 2, chaos: 3 };
function activeDifficulty() { return inTown ? diffOf(Math.max(1, dungeonReturn || 1)) : currentDifficulty(); }
function materialUnlocked(k) { return activeDifficulty() >= (MATERIAL_MIN_DIFF[k] || 1); }

// Per-point power weight of an attribute FOR THE CURRENT CLASS. Every attribute is
// worth the class-independent ATTR_POWER_WEIGHT (its derived-stat package); the
// class's damage attributes turn points into real Attack on top (attrDamage), so a
// point in your primary/secondary damage stat — or any Might, which always lends a
// little Attack — is worth more Power to you than to a class that can't hit with it.
function attrPowerWeight(key) {
  let w = ATTR_POWER_WEIGHT;
  const { primary, secondary } = classDmgAttrs();
  if (key === primary)        w += ATTR_DMG_PRIMARY   * ATTR_DMG_POWER;
  else if (key === secondary) w += ATTR_DMG_SECONDARY * ATTR_DMG_POWER;
  else if (key === 'might')   w += ATTR_FX.atkPerMight * ATTR_DMG_POWER; // universal Might dab
  return w;
}
// Per-point power weight of a gear STAT for the current class. Most stats are
// class-neutral (their table weight); Spell Power is scaled by how much the class
// actually casts (CLASS_SPELL_RELIANCE), so a caster values a Spell Power roll fully
// while it's near-dead weight on a pure-martial Warrior or Rogue.
function statPowerWeight(key) {
  let w = STAT_POWER_WEIGHTS[key] || 1;
  // Caster %s (Spell Power / Cast Speed) are weighted by how much the class casts;
  // martial-skill %s (Skill Power) by how much it leans on weapon skills — so a
  // Spell Power roll pads a Mage's Power but is near-dead weight on a Warrior, and
  // vice-versa for Skill Power. Keeps per-class Power tracking real gear impact.
  if (key === 'SPELLPWR' || key === 'CASTSPD') w *= (CLASS_SPELL_RELIANCE[player.class] ?? 1);
  else if (key === 'SKILLPWR') w *= (CLASS_SKILL_RELIANCE[player.class] ?? 1);
  return w;
}

// Total power of a single item, AS THIS CLASS would wield it: weighted sum of its
// stats + attributes + a rarity bonus. The same item can be worth different Power to
// different classes (a +Might affix or a Spell Power roll lands differently), which
// is the point — Power should track the item's real impact on this hero.
function itemPower(item) {
  if (!item || !item.stats) return 0;
  let p = 0;
  for (const [k, v] of Object.entries(item.stats)) {
    if (k === 'DMG') {
      const [lo, hi] = String(v).split('-').map(Number);
      p += ((lo + hi) / 2) * STAT_POWER_WEIGHTS.DMG;
    } else if (typeof v === 'number') {
      p += v * statPowerWeight(k);
    }
  }
  // Attribute affixes (+Might, +Luck, …) add to an item's power too, weighted by how
  // much THIS class gains from that attribute (attrPowerWeight).
  if (item.attrs) for (const [k, v] of Object.entries(item.attrs)) {
    if (typeof v === 'number') p += v * attrPowerWeight(k);
  }
  p += TIER_POWER_BONUS[item.tier] || 0;
  return Math.max(0, Math.round(p));
}

// Effective value of an attribute: the points spent (including the ATTR_BASE
// every hero starts with) plus any bonus carried on equipped gear (+13 Might,
// etc.). This — not the raw spent value — is what every derived stat reads.
function totalAttr(key) {
  const active = activeSlots();
  let sum = (player.attributes?.[key] || 0);
  for (const slot of SLOT_KEYS) {
    if (!active[slot]) continue;          // red/ignored pieces lend nothing
    const it = equipped[slot];
    if (it && it.attrs && typeof it.attrs[key] === 'number') sum += it.attrs[key];
  }
  return sum;
}

// The primary/secondary attributes a class deals damage with. Classless heroes
// (legacy saves mid-prompt) fall back to Might.
function classDmgAttrs() {
  const cls = playerClass();
  return (cls && cls.dmgAttrs) || { primary: 'might', secondary: null };
}
// Bonus attack damage contributed by the class's damage attributes — plus a
// small universal Might bonus so no class ever has a fully dead attribute.
function attrDamage() {
  const { primary, secondary } = classDmgAttrs();
  let d = totalAttr(primary) * ATTR_DMG_PRIMARY;
  if (secondary) d += totalAttr(secondary) * ATTR_DMG_SECONDARY;
  // Might always lends a little raw Attack power to EVERY class. Classes that
  // already scale damage off Might (Warrior primary / Rogue secondary) get far
  // more from it above, so this only matters when Might is otherwise off-class
  // (Mage, Templar) — there it's a weak-but-real contribution instead of zero.
  if (primary !== 'might' && secondary !== 'might') d += totalAttr('might') * ATTR_FX.atkPerMight;
  return d;
}
// Crit damage multiplier — equipment-only beyond the base, so gear (CRITDMG)
// drives how hard your crits land. Crit damage can swing freely up or down, but
// the multiplier never drops below 0 (no stat should ever read negative).
// Crit DAMAGE is a magnitude (not a chance), so it has no ceiling — stacking
// CRITDMG gear is a legitimate endgame payoff. Floored at 0 so a curse never
// reads negative.
function critDamageMult() { return Math.max(0, 2.0 + totalStat('CRITDMG') / 100 + skillBonus('critDmg')); }

// The player's overall power: a blend of level, attributes, and equipped gear.
// Red/ignored pieces (requirement no longer met) don't count — they give nothing.
function playerPower() {
  let p = player.level * 10;
  const active = activeSlots();
  for (const slot of SLOT_KEYS) if (active[slot]) p += itemPower(equipped[slot]);
  // Every allocated attribute point counts — the starting ATTR_BASE block AND points
  // spent on level-up — each weighted by how much THIS class gains from it
  // (attrPowerWeight), exactly like a gear attribute affix, so a point is worth the
  // same Power spent or geared and a damage-stat build reads stronger than an off-stat one.
  for (const k of ATTR_KEYS) p += (player.attributes?.[k] || 0) * attrPowerWeight(k);
  p += spentSkillPoints() * 5; // skill-tree investment shows up in Power too
  return Math.round(p);
}

// The true Power swing from equipping `item` into its slot — what the bag/shop
// "upgrade" arrows compare against. Beyond the piece it replaces, equipping a
// two-handed weapon also STRANDS an incompatible off-hand (loadItem stows it), so
// that off-hand's power belongs in the baseline. Without this, a 2H weapon could
// flag as a green upgrade while actually LOWERING your Power once the off-hand drops.
function equipUpgradeDelta(item) {
  if (!item || !item.slot) return 0;
  let baseline = equipped[item.slot] ? itemPower(equipped[item.slot]) : 0;
  if (item.slot === 'weapon' && equipped.offhand && offhandEquipError(equipped.offhand, item)) {
    baseline += itemPower(equipped.offhand);
  }
  return itemPower(item) - baseline;
}

// Max HP/MP are derived from level + attributes so the formula stays consistent
// across level ups, attribute spends, and loading an older save. Vitality drives
// HP and Spirit drives MP (each via ATTR_FX), and gear HP/MP add on top.
function baseMaxHp() {
  let hp = player.level*DEV.hpPerLevel + totalAttr('vitality') * ATTR_FX.hpPerVit + totalStat('HP');
  if (player.class === 'templar') hp = hp * 1.20; // Templar: hardier body
  hp = hp * (1 + skillBonus('maxHpPct') + foodFx('maxHpPct')); // skills + a hearty bowl of ramen
  hp = hp * diffDebuffMult();   // permanent scar from each difficulty conquered
  return Math.max(1, Math.round(hp));
}
function baseMaxMp() {
  let mp = player.level*2.5 + totalAttr('spirit') * ATTR_FX.mpPerSpr + totalStat('MP');
  if (player.class === 'mage') mp = mp * 1.20; // Mage: deeper mana pool
  mp = mp * (1 + skillBonus('maxMpPct') + foodFx('maxMpPct')); // skills + ramen
  return Math.max(0, Math.round(mp));
}
// Max Stamina: the flat MAX_STAMINA baseline plus a Might bonus, so a mighty
// hero carries a deeper sprint/dash reserve. Measured from Might above base so a
// fresh hero stays at the tuned 100.
function baseMaxStamina() {
  return Math.round(MAX_STAMINA + mightAboveBase() * ATTR_FX.enduPerMight);
}
// How fast Stamina refills (per second) once you stop exerting: the STAM_REGEN
// baseline plus a Might bonus, so Might shortens the downtime between sprints.
function staminaRegenPerSec() {
  return STAM_REGEN + mightAboveBase() * ATTR_FX.enduRegenPerMight;
}

// Total Defense: gear DEF plus a contribution from Vitality.
function playerDefense() {
  return totalStat('DEF') + totalAttr('vitality') * ATTR_FX.defPerVit + foodFx('defFlat');
}

// ── RATING-VS-LEVEL CHANCE SYSTEM ──
// Every percentage "chance" in the game (dodge, hit, crit, block, damage
// reduction) is derived the SAME way: an integer RATING you build from
// attributes + gear, contested against an OPPOSITION value that scales with the
// enemy's (floor) level:
//
//     chance = rating / (rating + opposition)
//
// This has no hard cap and needs none — for any finite rating the result is
// strictly below 1, so a chance can never reach, let alone exceed, 100%. You
// simply can't stack modifiers high enough; runaway numbers are mechanically
// unreachable rather than clamped. And because opposition grows with depth, a
// fixed rating buys LESS chance the deeper you go, so you must keep investing to
// stay sharp — there's no "max it once on floor 10 and coast". In true endgame,
// with extreme investment, you can still push a stat very high; just never
// trivially and never absolutely.
// rated() extracted to src/systems/ratings.js (imported at top).
// The floor/enemy level a chance is measured against. Combat passes the actual
// foe's level; menus/the hero sheet use the current floor (or the floor you'll
// return to from town) so a displayed % reflects "here, right now".
function curDepth() { return inTown ? Math.max(1, dungeonReturn || 1) : dungeonLevel; }
function oppLevel(e) { return (e && e.level) || curDepth(); }

// ── ENEMY OPPOSITION (scales with depth) ──
// Accuracy is contested by your Evasion (your dodge); Evasion by your Accuracy
// (your hit chance). Some foes are extra accurate or extra evasive (accMult /
// evaMult, default 1): an "accurate" foe punches through dodge, an "evasive" one
// is hard to hit without Accuracy.
function enemyAccuracyRating(e) {
  let m = (e && e.accMult) || 1;
  if (e && e.isBoss) m *= 1.35;        // guardians are hard to dodge
  else if (e && e.isElite) m *= 1.15;  // elites a touch harder
  return Math.round((32 + oppLevel(e) * DEV.enemyAccPerFloor) * m);
}
function enemyEvasionRating(e)  { return Math.round((6 + oppLevel(e) * 3) * ((e && e.evaMult) || 1)); }
// Generic depth resistance the player's crit/block/DR chances are rated against —
// deeper foes are harder to crit, block and shrug off.
function critOpposition(lvl)  { return 34 + (lvl || curDepth()) * 9; }
function blockOpposition(lvl) { return 30 + (lvl || curDepth()) * 9; }
function drOpposition(lvl)    { return 46 + (lvl || curDepth()) * 12; }

// ── PLAYER RATINGS (integers, from attributes + gear + skills/food/buffs) ──
// Accuracy keeps a level-scaled floor so ordinary attacks keep landing.
const ACC_BASE = 80, ACC_PER_LEVEL = 12;
// SKILL_RATING + ratePct() extracted to src/systems/ratings.js (imported at top).
// Agility drives BOTH Evasion and Accuracy; gear SPD/DODGE (legacy) read as flat
// evasion rating, the new ACC stat as accuracy. Rogues get an evasion/crit edge.
function playerEvasionRating() {
  let r = totalAttr('agility') * ATTR_FX.evaPerAgi
    + totalStat('SPD') + totalStat('DODGE')
    + ratePct(skillBonus('dodge')) + ratePct(buffMag('dodgeUp')) + ratePct(foodFx('dodgePct'));
  // Rogue's innate evasion scales with level so "harder to pin down" stays true
  // at depth (a flat bonus would wash out as opposition climbs each floor).
  if (player.class === 'rogue') r += 14 + player.level * 1.2;
  return Math.max(0, r);
}
function playerAccuracyRating() {
  return Math.max(0, ACC_BASE + player.level * ACC_PER_LEVEL
    + totalAttr('agility') * ATTR_FX.accPerAgi + totalStat('ACC') + ratePct(skillBonus('acc')));
}
// Agility you've built beyond the starting base — the input to the speed curves
// so a fresh hero (base Agility) sits at the tuned baseline and only investment
// or gear makes you faster. Never negative.
function agilityAboveBase() { return Math.max(0, totalAttr('agility') - ATTR_BASE); }
// Might beyond the starting base — feeds the Stamina pool/recharge bonuses so a
// fresh hero keeps the tuned baseline and only invested/geared Might raises them.
function mightAboveBase() { return Math.max(0, totalAttr('might') - ATTR_BASE); }
// Move-speed multiplier (≥1) from Agility: a soft-capping curve that always
// rewards more Agility yet never lets you blur past the AGI_MOVE_CAP ceiling.
function agiMoveMult() {
  const a = agilityAboveBase();
  return 1 + AGI_MOVE_CAP * a / (a + AGI_MOVE_SCALE);
}
// Attack-speed % from Agility (added alongside gear ATKSPD in the same /100
// denominator), soft-capped the same way so swings quicken but never go berserk.
function agiAtkSpeedPct() {
  const a = agilityAboveBase();
  return AGI_ATKSPD_CAP * a / (a + AGI_ATKSPD_SCALE);
}
function playerCritRating() {
  let r = totalAttr('luck') * ATTR_FX.critPerLuck + totalStat('CRIT') + totalStat('LCK')
    + ratePct(skillBonus('crit')) + ratePct(buffMag('critUp')) + ratePct(foodFx('critPct'));
  // Rogue's innate crit scales with level so "keener crits" keeps pace with the
  // rising crit opposition of deeper floors instead of fading to nothing.
  if (player.class === 'rogue') r += 12 + player.level * 1.2;
  return Math.max(0, r);
}
function playerBlockRating() { return Math.max(0, totalStat('BLOCK') + ratePct(skillBonus('block'))); }
function playerDRRating()    { return Math.max(0, totalStat('DR') + ratePct(skillBonus('dr'))); }

// ── EFFECTIVE CHANCES (what combat actually rolls; e is the foe, or {level} for UI) ──
function dodgeChanceVs(e) { return rated(playerEvasionRating(), enemyAccuracyRating(e)); } // player avoids the blow
function hitChanceVs(e)   { return rated(playerAccuracyRating(), enemyEvasionRating(e)); } // player's weapon lands
function critChanceVs(e)  { return rated(playerCritRating(), critOpposition(oppLevel(e))); }
function blockChanceVs(lvl) { return rated(playerBlockRating(), blockOpposition(lvl)); }
function drFractionVs(lvl)  { return rated(playerDRRating(), drOpposition(lvl)); }
// Back-compat shims for any caller that still wants a bare number against the
// current floor (the hero sheet, etc.).
function playerCritChance() { return critChanceVs({ level: curDepth() }); }
function playerDodge() { return dodgeChanceVs({ level: curDepth() }); }
function recomputeMaxStats() {
  player.maxHp = baseMaxHp();
  player.maxMp = baseMaxMp();
  // Build-defining item powers: Stalwart deepens max HP, Attuned max MP (stacking).
  const stal = itemPowerCount('stalwart'); if (stal) player.maxHp = Math.round(player.maxHp * (1 + 0.08 * stal));
  const att  = itemPowerCount('attuned');  if (att)  player.maxMp = Math.round(player.maxMp * (1 + 0.08 * att));
  player.maxStamina = baseMaxStamina();
  if (player.hp > player.maxHp) player.hp = player.maxHp;
  if (player.mp > player.maxMp) player.mp = player.maxMp;
  if (player.stamina > player.maxStamina) player.stamina = player.maxStamina;
}

// HP/MP regeneration as a REAL per-second rate. Single source of truth so the
// Stats panel can display the exact heal-per-second; applyRegen() banks the
// matching per-world-tick share each beat (see WORLD_TICK_SECONDS).
function hpRegenPerSec() {
  // The underlying stat/attribute/buff magnitudes are small per-beat trickles;
  // scaling by TICKS_PER_SEC expresses them as the smooth per-second rate the
  // player actually heals at. applyRegen banks the fractional amount so the HP
  // readout stays a clean integer rather than cliff-ing at low Vitality.
  let r = totalStat('REGEN') + totalAttr('vitality') * ATTR_FX.hpRegenPerVit;
  if (player.class === 'templar') r += 2; // Templar mends faster between fights
  r += skillBonus('hpRegen'); // Recovery / Divine Vigor passives
  r += buffMag('regen'); // Redeemer / Bastion regen buffs
  r += foodFx('regen'); // a warm bowl of ramen mends you between fights
  return r * TICKS_PER_SEC;
}
function mpRegenPerSec() {
  // A slow trickle on purpose: mana should run dry in sustained fights so mana
  // pots stay worth quaffing. Scaled to a real per-second rate; applyRegen banks
  // the fractional per-beat share so sub-1 regen works while MP stays an integer.
  return (0.15 + totalAttr('spirit') * ATTR_FX.mpRegenPerSpr + skillBonus('mpRegen')) * TICKS_PER_SEC;
}

