// Bosses guard every 5th floor. Each has a distinct fighting style: a movement
// `behavior` (see BEHAVIORS), a passive `ability` baked into its melee (lifesteal,
// curse procs, enrage…), and a `specials` kit of telegraphed tricks it weaves in
// mid-fight — walls of flame, chains that yank you in, barriers, shockwaves and
// more (dispatched by bossSpecial → tryBossAbility). The mix makes every guardian
// a real fight instead of a damage sponge that walks at you.
// `type` is an opaque identity key (unsaved, ephemeral); `sprite` is the pixel
// tile drawn for the guardian — referenced directly, never resolved from an emoji.
const BOSSES = [
  { type: 'ratking',     sprite: 'b_ratking',     name: 'Rat King',      floor: 5,  behavior: 'chaser', ability: 'summon',    blurb: 'swarms you with vermin, quakes the ground and whirls into the pack', size: 2,
    specials: ['summon','shockwave','walls','quake','whirlwind','summonelite'] },
  { type: 'inferno',     sprite: 'b_inferno',     name: 'Inferno Demon', floor: 10, behavior: 'caster', ability: 'firebolt',  blurb: 'walls the floor in flame, rains firestorms and looses volleys of fire', size: 2,
    specials: ['firewall','firestorm','blink','shield','volley','berserk'] },
  { type: 'dragon',      sprite: 'b_dragon',      name: 'Elder Dragon',  floor: 15, behavior: 'brute',  ability: 'enrage',    blurb: 'charges, whirls its tail, breathes fire and flies into a rage', size: 3,
    specials: ['enrage','firestorm','shockwave','chain','charge','whirlwind','berserk'] },
  { type: 'deathknight', sprite: 'b_deathknight', name: 'Death Knight',  floor: 20, behavior: 'chaser', ability: 'lifesteal', blurb: 'chains you in, siphons your life, raises champions and mends its wounds', size: 2,
    specials: ['chain','frost','heal','summon','drain','vortex','summonelite'] },
  { type: 'allseer',     sprite: 'b_allseer',     name: 'The All-Seer',  floor: 25, behavior: 'caster', ability: 'curse',     blurb: 'hexes and drains from afar, spits venom, drags you in and blinks away', size: 3,
    specials: ['curseblast','walls','blink','frost','shield','volley','venom','vortex','drain'] },
];

// ── ENEMY AI BEHAVIOURS ──
// Each archetype defines HOW a monster moves and fights, so foes feel distinct
// instead of all shuffling toward you in a line. The actual pathing toward the
// player is shared (BFS in enemyPathStep) — these flags layer personality on top.
//   speed     — tiles moved per world beat (swift vermin take two)
//   range     — how far it can strike (ranged casters reach across the room)
//   erratic   — chance per step to dart in a random direction instead
//   slow      — acts only every other world beat (heavy brutes), but hits harder
//   hitMult   — melee damage multiplier
//   ambush    — stays still until you're within N tiles, then pounces
//   ranged    — attacks from a distance and tries to keep its spacing
//   keepAway  — ranged foes back off when you close within this many tiles
//   packRush  — closes faster when you're wounded (wolves hunt in packs)
//   atkMult   — attack-CADENCE multiplier (time between swings; <1 jabs faster, >1 slower)
//   hitMult   — per-swing melee DAMAGE multiplier
//   hpMult    — max-HP multiplier vs the floor baseline (brutes tanky, vermin frail)
//   dmgMult   — base-damage multiplier vs the floor baseline
// Each archetype carries a distinct HP/damage profile, so a Bear (brute) and a Rat
// (swift) on the SAME floor genuinely differ in toughness and punch — not just sprite
// and movement. Combined with speed/cadence/range/ambush/pack/ranged, the seven
// archetypes each play differently.
const BEHAVIORS = {
  chaser:  { speed: 1, range: 1, atkMult: 1.0,  hpMult: 1.0,  dmgMult: 1.0 },
  swift:   { speed: 2, range: 1, erratic: 0.25, atkMult: 0.6,  hpMult: 0.6,  dmgMult: 0.7 },
  erratic: { speed: 1, range: 1, erratic: 0.6,  atkMult: 0.9,  hpMult: 0.7,  dmgMult: 0.8 },
  lurker:  { speed: 1, range: 1, ambush: 3,     atkMult: 0.85, hpMult: 1.0,  dmgMult: 1.2 },
  brute:   { speed: 1, range: 1, slow: true, hitMult: 1.5, atkMult: 1.7, hpMult: 2.0,  dmgMult: 1.15 },
  caster:  { speed: 1, range: 4, ranged: true, keepAway: 2, castChance: 0.7, atkMult: 1.2, hpMult: 0.7, dmgMult: 1.0 },
  pack:    { speed: 1, range: 1, packRush: true, atkMult: 0.8, hpMult: 0.85, dmgMult: 0.9 },
};
// Map each enemy sprite to a behaviour; anything unlisted hunts you down (chaser).
const ENEMY_BEHAVIOR = {
  '<span data-spr=e_rat></span>':'swift','<span data-spr=e_mouse></span>':'swift','<span data-spr=e_ant></span>':'swift','<span data-spr=e_cricket></span>':'swift','<span data-spr=e_beetle></span>':'swift','<span data-spr=e_roach></span>':'swift','<span data-spr=e_bee></span>':'swift','<span data-spr=e_mosquito></span>':'swift','<span data-spr=e_worm></span>':'swift',
  '<span data-spr=e_bat></span>':'erratic','<span data-spr=e_ghost></span>':'erratic','<span data-spr=e_skunk></span>':'erratic','<span data-spr=e_eagle></span>':'erratic',
  '<span data-spr=e_snake></span>':'lurker','<span data-spr=e_scorpion></span>':'lurker','<span data-spr=e_lizard></span>':'lurker','<span data-spr=e_octopus></span>':'lurker','<span data-spr=e_squid></span>':'lurker','<span data-spr=e_frog></span>':'lurker','<span data-spr=e_snail></span>':'lurker',
  '<span data-spr=e_bear></span>':'brute','<span data-spr=e_boar></span>':'brute','<span data-spr=e_rhino></span>':'brute','<span data-spr=e_bison></span>':'brute','<span data-spr=e_troll></span>':'brute','<span data-spr=e_trex></span>':'brute','<span data-spr=e_sauropod></span>':'brute','<span data-spr=e_dragon></span>':'brute','<span data-spr=b_dragon></span>':'brute','<span data-spr=e_lobster></span>':'brute','<span data-spr=e_zombie></span>':'brute','<span data-spr=e_croc></span>':'brute','<span data-spr=e_hedgehog></span>':'brute',
  '<span data-spr=e_vampire></span>':'caster','<span data-spr=e_imp></span>':'caster','<span data-spr=e_devil></span>':'caster','<span data-spr=e_alien></span>':'caster','<span data-spr=e_genie></span>':'caster',
  '<span data-spr=e_wolf></span>':'pack','<span data-spr=e_tiger></span>':'pack',
};
function behaviorFor(type) { return (typeof MONSTERS === 'object' && MONSTERS[type] && MONSTERS[type].behavior) || ENEMY_BEHAVIOR[type] || 'chaser'; }

// ── WEAPON ATTACK STYLES ──
// Each weapon base name swings differently, so loadout shapes how you fight:
//   slash  (Sword)  — balanced strike, light follow-through onto a 2nd foe
//   cleave (Axe)    — hits every adjacent enemy at once
//   flurry (Dagger) — two rapid lighter hits, extra crit
//   bolt   (Staff)  — magic blast at range, spends a little MP
//   shot   (Bow)    — fires across the room, no counterattack from afar
//   crush  (Mace)   — heavy blow that can stun
//   thrust (Spear)  — reaches one extra tile, striking without reprisal
//   reap   (Scythe) — wide arc that heals you for part of the damage dealt
const WEAPON_STYLES = {
  Sword:'slash', Axe:'cleave', Dagger:'flurry', Staff:'bolt',
  Bow:'shot', Mace:'crush', Spear:'thrust', Scythe:'reap',
};
function weaponStyle() {
  const w = activeWeapon();   // red/ignored weapon → unarmed style
  if (!w || !w.name) return 'fist';
  const sub = weaponSubType(w);
  if (sub) return WEAPON_SUBTYPES[sub].style;
  for (const base of Object.keys(WEAPON_STYLES)) {
    if (new RegExp('\\b' + base + '\\b').test(w.name)) return WEAPON_STYLES[base];
  }
  return 'slash';
}

// ── WEAPON REACH ──
// How many tiles ahead each weapon can strike (1 = melee, must be adjacent). This
// is the single source of truth shared by combat (tryRangedAttack) and the little
// range grid shown in the weapon tooltip and the Forge, so what you see matches
// what you can actually hit.
const WEAPON_RANGE = { Sword:1, Axe:1, Dagger:1, Staff:4, Bow:4, Mace:1, Spear:2, Scythe:1 };
// Same reach keyed by attack style, derived so combat code that works off the
// resolved style stays in lockstep with the table above.
const STYLE_RANGE = {};
for (const b in WEAPON_STYLES) STYLE_RANGE[WEAPON_STYLES[b]] = WEAPON_RANGE[b];
// One-line description of how each style swings — surfaced in the weapon tooltip
// and the Forge so a base's feel is legible without reading the source comment.
const WEAPON_STYLE_DESC = {
  slash:  'Balanced strike, light follow-through to a 2nd foe',
  cleave: 'Hits every adjacent foe at once',
  flurry: 'Two rapid strikes with extra crit',
  bolt:   'Magic blast at range (costs a little MP)',
  shot:   'Fires across the room — no reprisal from afar',
  crush:  'Heavy blow that can stun',
  thrust: 'Reaches an extra tile, striking without reprisal',
  reap:   'Wide arc that heals you for part of the hit',
};
// The reach of a base/sub-type, or of an item's resolved weapon type. A sub-type
// (Pike, Rapier) carries its own reach; a bare category falls back to the table.
function weaponRange(base) {
  if (WEAPON_SUBTYPES[base]) return WEAPON_SUBTYPES[base].range;
  return WEAPON_RANGE[base] || 1;
}
// The reach of an actual item, resolving its sub-type first (so a Pike reaches 3
// even though its 'thrust' style's category default is 2). Used by combat.
function weaponRangeOf(item) {
  if (!item) return 1;
  const sub = weaponSubType(item);
  if (sub) return WEAPON_SUBTYPES[sub].range;
  const cat = weaponBaseType(item);
  return (cat && WEAPON_RANGE[cat]) || 1;
}
// A tiny horizontal map of a weapon's reach: the gold tile is you, each red tile
// ahead is a square it can strike, so the reach reads at a glance. Shared by the
// weapon tooltip and the Forge preview.
function weaponRangeGridHTML(base) {
  const range = weaponRange(base);
  let cells = '';
  for (let i = 0; i <= range; i++) {
    const bg = i === 0 ? '#e3c344' : '#c0392b';
    const bd = i === 0 ? '#f4e08a' : '#e0556b';
    cells += `<span class="rg-cell" style="background:${bg};border-color:${bd}"></span>`;
  }
  return `<span class="range-grid">${cells}</span><span class="range-cap">reach ${range}</span>`;
}

// ── CHARACTER CLASSES ──
// Every class now starts with the SAME attributes (ATTR_BASE in each). A class's
// identity instead lives in `dmgAttrs` — the primary/secondary attributes its
// attacks scale off, so a Mage hits with Spirit while a Rogue hits with Agility —
// plus its passive and the weapon types it can wield. There is no always-on
// baseline skill: every hero starts with one skill point and learns its first
// active (Cleave / Backstab / Firebolt / Mend) from the tree.
// Off-class weapons still drop and sell, but can't
// be equipped (a hard lock — see canEquipItem). Class is chosen on a new game and
// can be re-picked at the town Trainer.
const CLASSES = {
  warrior: {
    name: 'Warrior', icon: 'w_sword', color: '#e08a3c',
    blurb: 'A frontline bruiser — hits hardest of the melee, lightly armoured.',
    passive: '+10% damage dealt · −10% damage taken',
    dmgAttrs: { primary: 'might', secondary: 'vitality' },
    weapons: ['Sword','Axe','Mace','Spear','Scythe'],
  },
  rogue: {
    name: 'Rogue', icon: 'w_dagger', color: '#5ec27a',
    blurb: 'A nimble striker — the deadliest weapon hits, but fragile.',
    passive: '+12% damage · crits & dodge that scale with level',
    dmgAttrs: { primary: 'agility', secondary: 'might' },
    weapons: ['Dagger','Sword','Bow'],
  },
  mage: {
    name: 'Mage', icon: 'ic_orb', color: '#7d9bff',
    blurb: 'A glass-cannon caster — a deep mana pool and ranged fire.',
    passive: '+30% max MP · +15% spell power · −10% damage taken',
    dmgAttrs: { primary: 'spirit', secondary: 'luck' },
    weapons: ['Staff','Dagger'],
  },
  templar: {
    name: 'Templar', icon: 'a_shield', color: '#e8c95a',
    blurb: 'A holy bulwark — the sturdiest hero, and mends its own wounds.',
    passive: '+20% max HP · −15% damage taken · stronger regen',
    dmgAttrs: { primary: 'vitality', secondary: 'spirit' },
    weapons: ['Sword','Mace','Spear'],
  },
};
const CLASS_KEYS = Object.keys(CLASSES);

function playerClass() { return player.class ? CLASSES[player.class] : null; }

// The base weapon type (Sword, Bow, …) of an item, or null if it isn't a known
// weapon. Drives class equip restrictions.
function weaponBaseType(item) {
  if (!item || !item.name) return null;
  // New items carry a sub-type word → resolve its category directly.
  const sub = weaponSubType(item);
  if (sub) return WEAPON_SUBTYPES[sub].cat;
  // Legacy bare-category weapons ("Ancient Sword of Power") keep the old match.
  for (const base of Object.keys(WEAPON_STYLES)) {
    if (new RegExp('\\b' + base + '\\b').test(item.name)) return base;
  }
  return null;
}

// ── STAT REQUIREMENTS ──
// EVERY gear slot — weapon, off-hand, armour AND jewelry — gates on a single
// ATTRIBUTE REQUIREMENT, computed live from the piece's base (weapon sub-type,
// off-hand base, or armour/jewelry base) and its ilvl — never stored on the item,
// so legacy saves and the Enchanter's rerolls keep working with zero migration.
// The required attribute is the one that base's natural wearer leans on, which
// nudges every class toward gear that fits it: heavy melee / heavy plate lean on
// Might or Vitality, finesse weapons & light armour on Agility, casting gear &
// cloth on Spirit, and fortune trinkets on Luck. A hero CAN still pick up an
// "off-class" piece — they just have to invest that attribute first. The gate
// scales with ilvl on a STEEPENING slope, so deeper gear demands an ever-growing
// investment and off-class dabbling gates out harder the further you descend:
//   need = round(8 + ilvl * slope * weight), slope = 0.9→1.35 with depth
//   (heavier bases carry a bigger weight; see attrReqValue for the full formula)
// Keyed by sub-type first; the bare CATEGORY keys are the legacy fallback for old
// bare-category weapons whose name carries no sub-type word.
const WEAPON_REQ = {
  // Swords
  'Shortsword':{ attr:'might',   w:0.90 }, 'Arming Sword':{ attr:'might',   w:1.00 },
  'Rapier':    { attr:'agility', w:0.78 }, 'Greatsword':  { attr:'might',   w:1.45 },
  'Claymore':  { attr:'might',   w:1.40 },
  // Axes
  'Hatchet':   { attr:'might',   w:0.95 }, 'War Axe':     { attr:'might',   w:1.10 },
  'Greataxe':  { attr:'might',   w:1.55 }, 'Battleaxe':   { attr:'might',   w:1.45 },
  // Daggers (finesse → Agility)
  'Dagger':    { attr:'agility', w:0.78 }, 'Stiletto':    { attr:'agility', w:0.75 },
  'Kris':      { attr:'agility', w:0.82 },
  // Maces
  'Mace':      { attr:'might',   w:1.05 }, 'Morningstar': { attr:'might',   w:1.12 },
  'Maul':      { attr:'might',   w:1.50 },
  // Spears
  'Spear':     { attr:'might',   w:0.95 }, 'Halberd':     { attr:'might',   w:1.40 },
  'Pike':      { attr:'might',   w:1.30 },
  // Staves (casting → Spirit)
  'Staff':     { attr:'spirit',  w:1.00 }, 'Wand':        { attr:'spirit',  w:0.85 },
  // Bows (ranged → Agility)
  'Shortbow':  { attr:'agility', w:0.88 }, 'Longbow':     { attr:'agility', w:0.95 },
  // Scythes
  'Scythe':    { attr:'might',   w:1.15 }, 'War Scythe':  { attr:'might',   w:1.42 },
  // Bare-category fallbacks for legacy weapons whose name has no sub-type word.
  // (Dagger/Mace/Spear/Staff/Scythe already appear above as identically-named
  // sub-types, so only Sword/Axe/Bow need a category-only entry here.)
  'Sword':     { attr:'might',   w:1.00 }, 'Axe':         { attr:'might',   w:1.05 },
  'Bow':       { attr:'agility', w:0.90 },
};
// Off-hands gate on the stat their family rewards: shields → Vitality (a tank
// commitment that scales with the shield's heft), caster off-hands → Spirit,
// quiver / parry-blade → Agility.
const OFFHAND_REQ = {
  'Buckler':{ attr:'vitality', w:0.55 }, 'Kite Shield':{ attr:'vitality', w:0.80 },
  'Tower Shield':{ attr:'vitality', w:1.10 }, 'Tome':{ attr:'spirit', w:0.90 },
  'Focus':{ attr:'spirit', w:0.70 }, 'Quiver':{ attr:'agility', w:0.70 },
  'Parrying Dagger':{ attr:'agility', w:0.75 },
};
// Longest base name first so "Parrying Dagger" / "Tower Shield" win over any shorter
// substring (mirrors SUBTYPE_KEYS' longest-first resolution).
const OFFHAND_REQ_KEYS = Object.keys(OFFHAND_REQ).sort((a, b) => b.length - a.length);
// Armour & jewelry, keyed by SLOT then by the base word in the item's name. Each
// base's equip requirement pairs with its signature innate (see BASE_STATS): the
// gate is the PRICE of the base's identity, and your primary attribute routes you
// to the base that rewards it. Per slot the bases spread across archetypes — a
// vitality-gated tank, a might-gated bruiser, an agility-gated evasion/offense
// piece and a spirit-gated caster piece (head adds a luck-gated farmer's Cap whose
// signature is Magic Find). Heavier bases carry the steeper weights (raw armour
// costs more attribute); jewelry spreads across all five attributes so every class
// has a fitting trinket in each slot. Weights are gentler than weapons' (armour is
// mandatory, so its gate shouldn't be brutal) and jewelry gentler still. Matched
// against the item's OWN slot only, so base words never collide across slots.
const ARMOR_REQ = {
  head: { 'Helm':{ attr:'vitality', w:0.80 }, 'Cap':{ attr:'luck', w:0.46 }, 'Hood':{ attr:'agility', w:0.55 },
          'Crown':{ attr:'spirit', w:0.62 }, 'Circlet':{ attr:'spirit', w:0.55 } },
  chest:{ 'Chestplate':{ attr:'vitality', w:0.95 }, 'Cuirass':{ attr:'might', w:0.78 }, 'Mail':{ attr:'might', w:0.82 },
          'Tunic':{ attr:'agility', w:0.55 }, 'Robe':{ attr:'spirit', w:0.55 } },
  hands:{ 'Gauntlets':{ attr:'might', w:0.60 }, 'Bracers':{ attr:'vitality', w:0.48 },
          'Grips':{ attr:'agility', w:0.46 }, 'Gloves':{ attr:'spirit', w:0.42 } },
  legs: { 'Greaves':{ attr:'vitality', w:0.78 }, 'Tassets':{ attr:'might', w:0.62 },
          'Trousers':{ attr:'agility', w:0.48 }, 'Leggings':{ attr:'spirit', w:0.46 } },
  ring: { 'Signet':{ attr:'might', w:0.42 }, 'Band':{ attr:'vitality', w:0.42 },
          'Loop':{ attr:'spirit', w:0.42 }, 'Ring':{ attr:'luck', w:0.42 } },
  amulet:{ 'Necklace':{ attr:'spirit', w:0.48 }, 'Pendant':{ attr:'vitality', w:0.45 }, 'Talisman':{ attr:'luck', w:0.42 },
           'Amulet':{ attr:'might', w:0.45 }, 'Charm':{ attr:'agility', w:0.40 } },
};
// Per-slot base words, longest-first, so a substring base never shadows a longer one.
const ARMOR_REQ_KEYS = {};
for (const s in ARMOR_REQ) ARMOR_REQ_KEYS[s] = Object.keys(ARMOR_REQ[s]).sort((a, b) => b.length - a.length);
// The {attr,w} an armour/jewelry item carries, found by matching its base word
// within its OWN slot's table (so "Ring" can't shadow a chest's "Mail", etc.).
function armorReqDef(item) {
  const tbl = ARMOR_REQ[item.slot];
  if (!tbl) return null;
  const nm = item.name || '';
  for (const k of ARMOR_REQ_KEYS[item.slot]) if (nm.includes(k)) return tbl[k];
  return null;
}
// The required attribute amount for an item of the given ilvl and per-type weight.
// Clamped so a missing/odd ilvl (very old saves) can never NaN or read as zero.
// TWO axes make the deepest, flashiest gear demand a real, class-defining stake:
//   • DEPTH — the per-ilvl slope STEEPENS with item level (0.9 → 1.35, ramping
//     across the finite tiers and capping past the deepest finite floor), so a
//     piece's gate claims a GROWING share of your attribute budget the deeper you
//     find it. Early gear stays broadly wearable, but deep gear can only be met by
//     an attribute you've truly committed to — which is your class's one or two —
//     so an off-class piece gates out ever harder the further you descend.
//   • RARITY — the whole thing is then scaled ~8% per rarity step above normal, so
//     a legendary/unique piece gates harder than a plain one of equal ilvl.
function tierReqMult(tier) {
  const rank = Object.keys(TIERS).indexOf(tier);
  return 1 + 0.08 * ((rank < 0 ? 1 : rank) - 1); // normal (rank 1) = 1.0 baseline
}
function attrReqValue(ilvl, w, tier) {
  const lv = Math.max(1, ilvl || 1);
  // Slope ramps 0.9 → 1.35 across the finite tiers (0.006/ilvl, capped at +0.45
  // around the deepest finite floor), so the gate outpaces a spread-thin build the
  // deeper you go and rewards committing points to your class's attributes.
  const slope = 0.9 + Math.min(0.45, lv * 0.006);
  return Math.round((8 + lv * w * slope) * tierReqMult(tier));
}
// The {attr, need} a piece demands to equip, or null if it carries no requirement
// (non-gear, or an unrecognisable legacy item → fail OPEN so a save never bricks).
function itemAttrReq(item) {
  if (!item) return null;
  let def = null;
  if (item.slot === 'weapon') {
    const sub = weaponSubType(item);
    def = (sub && WEAPON_REQ[sub]) || WEAPON_REQ[weaponBaseType(item)] || null;
  } else if (item.slot === 'offhand') {
    const nm = item.name || '';
    for (const k of OFFHAND_REQ_KEYS) if (nm.includes(k)) { def = OFFHAND_REQ[k]; break; }
  } else if (ARMOR_REQ[item.slot]) {
    def = armorReqDef(item);
  }
  return def ? { attr: def.attr, need: attrReqValue(item.ilvl, def.w, item.tier) } : null;
}
// Live status of a piece's stat gate. `have` is the attribute you have AVAILABLE to
// meet it (see reqAttrAvail): your base points plus the +attrs from every OTHER
// active worn piece, never the piece's own bonus. So a candidate in the bag can't
// bootstrap its own requirement, and — crucially — a WORN piece you can no longer
// support (e.g. after a respec) reads as NOT met, which is exactly what turns it
// red in the gear panel and stops it counting (see activeSlots).
function attrReqStatus(item) {
  const r = itemAttrReq(item);
  if (!r) return null;
  const have = reqAttrAvail(item, r.attr);
  return { attr: r.attr, need: r.need, have, ok: have >= r.need };
}
// A short reason a piece's stat gate isn't met (for the lock tooltip / log), or null.
function attrReqError(item) {
  const s = attrReqStatus(item);
  if (!s || s.ok) return null;
  return `Requires ${s.need} ${ATTRIBUTES[s.attr].short} (you have ${s.have}).`;
}

// Weapon categories that count as melee (a parrying dagger pairs with these).
const MELEE_CATS = new Set(['Sword', 'Axe', 'Mace', 'Spear', 'Dagger', 'Scythe']);
// The off-hand family of an item (shield / caster / ranged / dual), recorded on
// item.off at generation; defaults to shield for any older/oddly-shaped off-hand.
function offhandFamily(item) { return (item && item.off) || 'shield'; }
// Why an off-hand can't be equipped alongside `weapon` (the current main hand, may
// be null), or null if the pairing is allowed. Each off-hand wants a fitting main
// hand: a quiver feeds a BOW (and is back-worn, so it's exempt from the two-hander
// rule), a parrying dagger needs a one-handed MELEE weapon to dual with, and a
// shield/focus just needs a free hand (a 1H weapon or none). Titan's Grip frees the
// hand a two-hander would otherwise take.
function offhandEquipError(item, weapon) {
  if (!item || item.slot !== 'offhand') return null;
  const fam = offhandFamily(item);
  const w = weapon;
  if (fam === 'ranged') {
    return (w && weaponBaseType(w) === 'Bow') ? null : 'A quiver only works with a bow.';
  }
  if (w && isTwoHander(w) && !skillFlag('titangrip')) {
    return 'A two-handed weapon leaves no hand free for an off-hand.';
  }
  if (fam === 'dual') {
    if (!w || weaponHandsOf(w) !== 1 || !MELEE_CATS.has(weaponBaseType(w))) {
      return 'A parrying dagger needs a one-handed melee weapon in your main hand.';
    }
  }
  return null; // shield / caster: any one-handed weapon or a free hand works
}

// ── EFFECTIVE (NON-IGNORED) GEAR ──
// A worn piece only COUNTS — for stats, attributes, weapon damage and its own frame
// colour — while it still MEETS its attribute requirement (and, for an off-hand,
// still pairs with the main hand). A piece you could no longer equip — the classic
// case being a respec that drops your attributes below what a heavy chestplate or
// greatsword demanded — turns red in the gear panel and is IGNORED until you
// re-qualify, instead of silently keeping its power.
//
// Because one piece's +attributes can be exactly what lets ANOTHER piece meet its
// gate, and an ignored piece must lend nothing, the active set is resolved by
// FIX-POINT: assume every worn piece active, then repeatedly drop any whose gate
// isn't met by the attributes of the pieces STILL active (a piece never counts its
// own +attr toward its own gate — the same rule as the equip check). Dropping only
// removes, so it settles in at most SLOT_KEYS.length passes. Computed on demand
// (no cache): it's only hit on player actions and panel renders, never a tight loop.
// Core resolver, parameterised by `getItem(slot)` so the SAME fix-point serves both
// the live loadout AND a hypothetical "what if I equipped this candidate" swap (the
// candidate occupies its slot, the piece it replaces is gone). Returns the settled
// active map plus `attrFrom(key, exceptSlot)` = base points + the +attrs of the
// pieces held active in that loadout, excluding one slot.
function resolveActive(getItem) {
  const active = {};
  for (const slot of SLOT_KEYS) active[slot] = !!getItem(slot);
  const attrFrom = (key, exceptSlot) => {
    let sum = player.attributes?.[key] || 0;
    for (const slot of SLOT_KEYS) {
      if (slot === exceptSlot || !active[slot]) continue;
      const it = getItem(slot);
      if (it && it.attrs && typeof it.attrs[key] === 'number') sum += it.attrs[key];
    }
    return sum;
  };
  let changed = true;
  while (changed) {
    changed = false;
    for (const slot of SLOT_KEYS) {
      if (!active[slot]) continue;
      const it = getItem(slot);
      const r = itemAttrReq(it);
      const gateOk = !r || attrFrom(r.attr, slot) >= r.need;
      // An off-hand also has to still pair with whatever is in the main hand (an
      // unmet pairing — e.g. a quiver with no bow — also ignores the piece).
      const pairOk = slot !== 'offhand' || !offhandEquipError(it, getItem('weapon'));
      if (!gateOk || !pairOk) { active[slot] = false; changed = true; }
    }
  }
  return { active, attrFrom };
}
function activeSlots() { return resolveActive(s => equipped[s]).active; }
// Is the piece in this slot worn AND currently counting (not red/ignored)?
function slotActive(slot) { return !!equipped[slot] && activeSlots()[slot]; }
// The main-hand weapon IF it currently counts, else null — so a red/ignored weapon
// falls back to bare fists for damage, attack style and reach.
function activeWeapon() { return slotActive('weapon') ? equipped.weapon : null; }
// The off-hand IF it currently counts, else null — so a red/ignored off-hand grants
// no loadout-conditional passives (shield/caster/dual bonuses) either.
function activeOffhand() { return slotActive('offhand') ? equipped.offhand : null; }
// Attributes AVAILABLE for `item` to meet its gate IF it occupied its slot. Resolves
// the fix-point over the SWAPPED loadout (item in its slot, the piece it would
// replace removed), so the answer accounts for any cascade where that replaced piece
// was propping up ANOTHER piece — a candidate the loot list would otherwise green-
// light only to have it land red. For the piece already worn in its slot this is
// identical to the live active set. A piece never counts its own +attr (exclude-self).
function reqAttrAvail(item, key) {
  const slot = item.slot;
  return resolveActive(s => (s === slot ? item : equipped[s])).attrFrom(key, slot);
}

// Can the loadout equip this item right now? Every gear slot gates on its attribute
// requirement; an off-hand must ALSO pair with the equipped main-hand weapon.
function canEquipItem(item) {
  if (!item) return true;
  if (item.slot === 'offhand') return offhandEquipError(item, equipped.weapon) === null && attrReqError(item) === null;
  // Weapon, armour and jewelry: the attribute requirement is the only gate.
  return attrReqError(item) === null;
}
// A short, human reason this item can't be equipped right now (for the loot lock
// tooltip), or '' if it can.
function equipLockReason(item) {
  if (!item) return '';
  // Off-hands fail for a bad main-hand pairing first, then for an unmet stat gate.
  if (item.slot === 'offhand') return offhandEquipError(item, equipped.weapon) || attrReqError(item) || '';
  // Weapon, armour and jewelry: the attribute requirement is the only equip lock.
  return attrReqError(item) || '';
}

// Combat passives keyed off the chosen class — now also folding in any damage
// passives bought on the skill tree (see skillBonus). Every class carries an
// innate damage-dealt / damage-taken lean so each plays to a distinct identity
// and all four stay viable, rather than the Warrior being the one safe pick:
//   Warrior  — the damage bruiser: hits hardest of the melee, lightly armoured.
//   Rogue    — the glass striker: top physical multiplier, but fragile.
//   Mage     — the glass cannon: spell power (see spellPowerMult) + thin padding.
//   Templar  — the bulwark: takes the least and (with +20% HP & regen) outlasts
//              everything, paying for it with no innate damage bonus.
// Spell damage is boosted for the Mage in spellPowerMult, not here, since this
// dealt multiplier only applies to physical hits (see applyOffenseMods).
const CLASS_DMG_DEALT = { warrior: 1.10, rogue: 1.12, mage: 1.00, templar: 1.00 };
const CLASS_DMG_TAKEN = { warrior: 0.90, rogue: 0.95, mage: 0.90, templar: 0.85 };
// How much each class leans on spell damage, used only to value the Spell Power gear
// stat in Power (statPowerWeight): a Mage lives on spells, a Templar casts holy
// smites alongside melee, and a Warrior/Rogue barely cast — so Spell Power is near-
// dead weight for them and shouldn't pad their Power as if it were a caster's.
const CLASS_SPELL_RELIANCE = { warrior: 0.25, rogue: 0.25, mage: 1.0, templar: 0.7 };
// The martial mirror of CLASS_SPELL_RELIANCE: how much each class leans on WEAPON
// active skills, used to value the Skill Power gear stat in Power (statPowerWeight).
// Melee classes live on skills; the Mage barely swings, so Skill Power is near-dead
// weight on it — the inverse of the spell reliance above.
const CLASS_SKILL_RELIANCE = { warrior: 1.0, rogue: 1.0, mage: 0.35, templar: 0.85 };
function classDmgDealtMult() {
  const base = CLASS_DMG_DEALT[player.class] || 1;
  return base * (1 + skillBonus('dmgDealt'));
}
function classDmgTakenMult() {
  const base = CLASS_DMG_TAKEN[player.class] || 1;
  // Iron Hide / Aegis / Juggernaut etc. shave a slice off every blow; clamp so a
  // fully-stacked defence build can never reach zero (no free invulnerability).
  return Math.max(0.1, base * (1 - skillBonus('dmgTaken')));
}

// ── SKILL TREES (v4) ──
// Each class has a separate PASSIVE tree and ACTIVE tree, 30 nodes each, laid out
// in 6 bands (rows) of 5. Every node maxes at rank 10. The PASSIVE trees are now a
// branching DAG, not straight ladders: nodes link via `req` (ALL prereqs) and
// `reqAny` (any-of merges), and many carry a CONDITIONAL bonus — `cfx` that only
// applies while its `cond` is true (e.g. "+damage with a two-handed weapon", "+block
// with a shield"). A few are build-defining keystones that flip a `flag`/`unlock`
// (Titan's Grip → off-hand with a 2H weapon, Dual Mastery → off-hand swing, Aegis →
// raise the block cap) or pair power with a real cost (negative fx). See skillBonus
// (folds cfx), condMet (evaluates conds), skillFlag, and pointsInTree (pts gates).
// Ascending (see ASCENSIONS) unlocks a focused specialization "PATH" tree.
const SKILL_POINTS_PER_LEVEL = 1;
// Every hero begins with one skill point to spend, so a fresh character can
// immediately learn its first active (Cleave / Backstab / Firebolt / Mend)
// instead of being handed an always-on baseline skill.
const SKILL_POINTS_AT_START = 1;
// Total skill points a hero of the given level has earned over its lifetime
// (the starting point plus one per level gained). Used to grant the right pool
// on a new game and to reconcile older saves on load.
function earnedSkillPoints(level) {
  return SKILL_POINTS_AT_START + Math.max(0, (level || 1) - 1) * SKILL_POINTS_PER_LEVEL;
}
// band index → minimum hero level for base trees, and for ascension PATH trees.
const SKILL_BANDS = [1, 4, 8, 13, 19, 26];
const ASC_BANDS   = [20, 25, 31];
const ASCEND_LEVEL = 20;   // level at which the Trainer offers ascension

// Build a tree from rows of node literals: assigns band/col/type/max/lvl and a
// default prerequisite (the node directly above in the previous row) unless the
// node already declares `req`. Ascension nodes (asc set) use ASC_BANDS for level.
// Tier → minimum hero level for a WEB-laid-out tree (band index 0..n). Webs use
// fewer, deeper tiers than the old 6-band grid.
const WEB_BANDS = [1, 4, 9, 16, 24, 30];
// Build a free-form WEB tree: a flat list of nodes that each carry their own
// position (x,y in 0..1) and explicit req/reqAny edges, so a class path can branch
// and re-converge into a web instead of a straight column. `band` is kept only to
// gate by level (via WEB_BANDS); positions come from x/y, not a grid.
function buildWeb(nodes, kind, ascId) {
  for (const n of nodes) {
    n.type = n.t || kind; delete n.t;
    n.max = n.keystone ? 1 : (n.max || 10);
    if (ascId) n.asc = ascId;
    n.lvl = n.lvl != null ? n.lvl : (WEB_BANDS[Math.min(n.band || 0, WEB_BANDS.length - 1)] || 1);
    if (n.col == null) n.col = 0;
  }
  return nodes;
}
function buildTree(rows, kind, ascId) {
  const out = [];
  rows.forEach((row, b) => {
    row.forEach((n, c) => {
      n.band = b; n.col = c;
      n.type = n.t || kind; delete n.t;
      // Keystones are single-rank build-definers; everything else ranks to 10.
      n.max = n.keystone ? 1 : (n.max || 10);
      if (ascId) n.asc = ascId;
      n.lvl = (ascId ? ASC_BANDS : SKILL_BANDS)[b];
      // Auto-link a node to the one directly above it ONLY when it declares no
      // explicit prerequisite of its own. A DAG node uses `req` (AND of all) and/or
      // `reqAny` (OR of any), and a `root:true` node opens with no prereq at all —
      // that's what turns the old straight ladders into a branching web.
      if (!n.req && !n.reqAny && !n.root && b > 0) {
        const prev = rows[b - 1];
        const parent = prev[Math.min(c, prev.length - 1)];
        n.req = [parent.id];
      }
      out.push(n);
    });
  });
  return out;
}

