// Aliases kept for older callers.
function toggleMusic() { cycleMusic(); }
function toggleSfx()   { cycleSfx(); }
// Fill a 5-bar level meter to `level` bars.
function renderVolMeter(el, level) {
  if (!el) return;
  let bars = '';
  for (let i = 1; i <= AUDIO_LEVELS; i++) bars += `<i class="vb${i <= level ? ' on' : ''}"></i>`;
  el.innerHTML = bars;
}
function updateMusicButton() {
  const ic = document.getElementById('music-icon');
  if (ic) ic.innerHTML = audio.musicLevel > 0 ? MUSIC_ON_SVG : MUSIC_OFF_SVG;
  const btn = document.getElementById('music-action');
  if (btn) btn.classList.toggle('muted', audio.musicLevel <= 0);
  renderVolMeter(document.getElementById('music-meter'), audio.musicLevel);
}
function updateSfxButton() {
  const ic = document.getElementById('sfx-icon');
  if (ic) ic.innerHTML = audio.sfxLevel > 0 ? SOUND_ON_SVG : SOUND_OFF_SVG;
  const btn = document.getElementById('sfx-action');
  if (btn) btn.classList.toggle('muted', audio.sfxLevel <= 0);
  renderVolMeter(document.getElementById('sfx-meter'), audio.sfxLevel);
}
function updateSoundButtons() { updateMusicButton(); updateSfxButton(); }
// Back-compat for any lingering "all sound" caller (e.g. an old title toggle).
function toggleSound() { cycleMusic(); cycleSfx(); }

// Flip the sprint control between HOLD and TOGGLE. Switching to HOLD also drops
// any latched auto-sprint so it can't stay stuck on. Persisted so the choice
// survives reloads.
function toggleSprintMode() {
  sprintMode = sprintMode === 'hold' ? 'toggle' : 'hold';
  if (sprintMode === 'hold') sprintLatched = false;
  try { localStorage.setItem(SPRINT_MODE_KEY, sprintMode); } catch (e) {}
  settingsChanged();
  sfx('click');
  updateSprintButton();
}
function updateSprintButton() {
  const lbl = document.getElementById('sprint-label');
  if (lbl) lbl.textContent = sprintMode === 'toggle' ? 'SPRINT: TOGGLE' : 'SPRINT: HOLD';
  const btn = document.getElementById('sprint-action');
  if (btn) btn.classList.toggle('on', sprintMode === 'toggle');
}

