for (const pack of terrainPacksInUse()) log(`🌍 Terrain tiles from "${pack.label}" by ${pack.credit} (${pack.license}).`);
log('🌿 Decor (trees, plants, cacti, shells) from the "[LPC]" collections by bluecarrot16 & contributors (CC-BY-SA) — full credits in docs/asset-credits.md.');

// PREVIEW ONLY — `?terrain=proc` swaps the dungeon ground to the procedural
// terrain-pack renderer; add `&preview=1` to auto-drop into a dungeon floor so
// the swap is visible immediately (used to screenshot a real level). Never fires
// in normal play.
try {
  const _q = new URLSearchParams(location.search);
  if (_q.get('terrain') === 'proc') PROC_TERRAIN = true;
  if (_q.get('preview') === '1') {
    setTimeout(() => {
      try {
        player.name = player.name || 'Preview';
        chooseClass(player.class || 'warrior');
        if (typeof closeTitle === 'function') closeTitle();
        enterDungeonAt(1, 6);
        if (typeof closeTitle === 'function') closeTitle();
      } catch (e) { console.error('preview bootstrap failed:', e); }
    }, 400);
    // Preview helper: jump to any raw dungeon depth (bypasses the unlock clamp)
    // and report its terrain mix, so a capture script can find water/lava floors.
    window.__previewFloor = function (lvl) {
      try {
        dungeonLevel = Math.max(1, lvl | 0);
        try { tutorialActive = false; } catch (e) {}
        try { floorThemeOverride = null; } catch (e) {}
        revivedInTown = false; closeTown(); recordDepth();
        statusEffects = []; setPlayerCell(5, 5); arrivalDir = 'down';
        generateMap();
        // keep the throwaway preview hero alive on deep floors long enough to
        // screenshot (deep enemies would one-shot a level-1 hero otherwise)
        player.hp = player.maxHp = 9999999; player.mp = player.maxMp = 9999999;
        if (typeof closeTitle === 'function') closeTitle();
        updateBars(); draw();
        let w = 0, l = 0, trees = 0, decor = 0;
        for (const k in decorMap) { decor++; if (DECOR_INDEX[decorMap[k]].ht >= 2.4) trees++; }
        for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) { const t = mapData[y][x]; if (t === 6) w++; else if (t === 7) l++; }
        return { level: lvl, biome: (currentTheme().name || ''), water: w, lava: l, trees, decor };
      } catch (e) { return { err: String(e) }; }
    };
    // Position the hero just behind the TALLEST tree (prefer directly north) to
    // showcase occlusion. Clears the one-time depth banner for a clean shot.
    window.__previewBehindTree = function () {
      const open = (x, y) => mapData[y] && mapData[y][x] === 0 && furnitureMap[y + ',' + x] === undefined;
      const trees = [];
      for (const k in decorMap) { const d = DECOR_INDEX[decorMap[k]]; if (d && d.ht >= 2.0) { const c = k.split(','); trees.push({ tx: +c[1], ty: +c[0], ht: d.ht }); } }
      trees.sort((a, b) => b.ht - a.ht); // tallest first
      for (const T of trees) {
        const hx = T.tx, hy = T.ty - 1; // directly north → under the canopy
        if (open(hx, hy)) {
          setPlayerCell(hx, hy); player.fx = hx + 0.5; player.fy = hy + 0.5;
          draw();
          return { tx: T.tx, ty: T.ty, ht: T.ht, hx, hy, ok: true };
        }
      }
      draw(); return { ok: false };
    };
    // Preview A/B: toggle the clustered secondary/tertiary floor accents on the
    // CURRENT map (no regen) so a capture can shoot the same layout both ways.
    window.__previewMultiFloor = function (on) { previewFlatFloor = !on; draw(); return { multiFloor: on }; };
    // Render the EXACT terrain autotile set the current level composites (floor +
    // accents + wall + water + lava), straight from the live atlas — so what we
    // inspect always matches what's on screen. Returns a labeled contact sheet.
    window.__previewTileset = function () {
      const C = currentTheme();
      const B = C.indoor ? indoorRoles(C) : (LPC_BIOME[C.name] || { floor: 'Grass', wall: 'Rock_Gray', water: 'Water' });
      const roles = [];
      if (B.floor)  roles.push(['floor (primary)', B.floor]);
      if (B.floor2) roles.push(['floor accent 2', B.floor2]);
      if (B.floor3) roles.push(['floor accent 3', B.floor3]);
      if (B.wall)   roles.push(['WALL', B.wall]);
      if (B.water)  roles.push(['water', B.water]);
      roles.push(['lava', 'Lava']);
      const A = LPC_A, NC = LPC_NCOLS, Z = 4, order = [15, 1, 2, 4, 8, 3, 5, 10, 12, 7, 11, 13, 14, 6, 9];
      const rowH = A * Z + 26;
      const cv = document.createElement('canvas');
      cv.width = order.length * (A * Z + 3) + 16; cv.height = roles.length * rowH + 12;
      const g = cv.getContext('2d'); g.imageSmoothingEnabled = false;
      g.fillStyle = '#15131b'; g.fillRect(0, 0, cv.width, cv.height);
      roles.forEach(([label, name], ri) => {
        const tbl = LPC_TABLE.table[name] || {};
        const y = 10 + ri * rowH;
        g.fillStyle = '#e8c267'; g.font = 'bold 14px monospace';
        g.fillText(label + ':  ' + name, 10, y + 13);
        order.forEach((m, ci) => { const id = tbl[m]; if (id == null) return; const sx = (id % NC) * A, sy = ((id / NC) | 0) * A; g.drawImage(lpcSheet, sx, sy, A, A, 10 + ci * (A * Z + 3), y + 18, A * Z, A * Z); });
      });
      return { biome: C.name, indoor: !!C.indoor, roles: roles.map((r) => r[0] + '=' + r[1]), img: cv.toDataURL('image/png') };
    };
    // Debug overlay: paint each SOLID (furnitureMap) tile red over the current
    // frame, so a screenshot shows whether collision lines up with the sprites.
    window.__previewSolids = function (on) { previewDrawSolids = on !== false; draw(); return { solids: Object.keys(furnitureMap).length }; };
    // Force a specific built-interior theme and regenerate, so indoor floors can be
    // previewed deterministically (normally they appear ~28% of floors at random).
    window.__previewIndoor = function (idx) {
      try {
        previewForceIndoor = (idx | 0);
        tutorialActive = false;
        revivedInTown = false; closeTown(); recordDepth();
        statusEffects = []; setPlayerCell(5, 5); arrivalDir = 'down';
        generateMap();
        player.hp = player.maxHp = 9999999; player.mp = player.maxMp = 9999999;
        if (typeof closeTitle === 'function') closeTitle();
        updateBars(); draw();
        let decor = 0, solid = 0;
        for (const k in decorMap) { decor++; if (DECOR_SOLID[decorMap[k]]) solid++; }
        const C = currentTheme();
        return { theme: C.name, floorStyle: C.floorStyle, wallStyle: C.wallStyle, decor, solid };
      } catch (e) { return { err: String(e) }; }
    };
  }
} catch (e) {}

